window.SEARCH=[{"t": "1. Data Ingestion, Pipelines & Governance", "u": "ingestion.html", "s": "Section"}, {"t": "1.1 Fixed-size chunking that ignores document structure", "u": "ingestion.html#fixed-size-chunking", "s": "Ingestion & Data Pipelines", "k": "Quality Chunking is a modelling decision  not a preprocessing default  Chunk along document structure  carry the heading path into every chunk  and prove the choice with a retrieval eval "}, {"t": "1.2 No metadata or lineage on chunks", "u": "ingestion.html#no-metadata-lineage", "s": "Ingestion & Data Pipelines", "k": "Compliance Quality If you can t answer  where did this answer come from  which version  and who approved it   the system isn t production ready for a regulated client "}, {"t": "1.3 Parsing PDFs, tables and scans as flat text", "u": "ingestion.html#flat-pdf-tables", "s": "Ingestion & Data Pipelines", "k": "Quality In document heavy industries the parser is the most underrated component  Bad parsing produces confident wrong numbers that no prompt can fix "}, {"t": "1.4 One-time ingestion with no incremental refresh or deletes", "u": "ingestion.html#one-time-ingestion", "s": "Ingestion & Data Pipelines", "k": "Reliability Compliance A RAG index is a replica of the enterprise s knowledge  Treat it like any replica  with change data capture  delete propagation and a freshness SLA "}, {"t": "1.5 Ingesting PII and secrets without redaction", "u": "ingestion.html#pii-ingestion", "s": "Ingestion & Data Pipelines", "k": "Security Compliance Data protection has to happen before embedding  Once PII is in the vector store  the logs and the caches  it can no longer be cleaned up reliably "}, {"t": "1.6 Rebuilding the whole index every night", "u": "ingestion.html#nightly-full-rebuild", "s": "Ingestion & Data Pipelines", "k": "Cost Reliability Scale Re embed what changed  not what exists  Change data capture plus a weekly reconciliation beats nightly rebuilds on cost and freshness "}, {"t": "1.7 CRM export column renamed, plan names vanish from the index", "u": "ingestion.html#data-01", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Data you depend on needs a contract "}, {"t": "1.8 OCR misreads income documents with no confidence check", "u": "ingestion.html#data-02", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech Extracted data needs a confidence score and a cross check "}, {"t": "1.9 No freshness SLO for promotion pages", "u": "ingestion.html#data-03", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Every source needs a freshness target "}, {"t": "1.10 After a bank merger, customer ids collide across systems", "u": "ingestion.html#data-04", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech Critical Join on identity you can trust  not on ids that happen to match "}, {"t": "1.11 Can't tell which version of a document produced an answer", "u": "ingestion.html#data-05", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Every answer should point to a version  not just a document "}, {"t": "1.12 Intent labels from three vendors disagree", "u": "ingestion.html#data-06", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Labels need a rulebook and a referee "}, {"t": "1.13 HR and legal files indexed into the employee assistant", "u": "ingestion.html#data-07", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech Critical Index by permission and classification  not by location "}, {"t": "1.14 Usage events arrive late and the bill-shock alert is wrong", "u": "ingestion.html#data-08", "s": "Ingestion & Data Pipelines", "k": "Quality Latency Telco Show when the data is from  not just what it says "}, {"t": "1.15 Backfill job duplicates every chunk in the vector store", "u": "ingestion.html#data-09", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech Every pipeline run should be safe to repeat "}, {"t": "1.16 Production call records copied unmasked into dev", "u": "ingestion.html#data-10", "s": "Ingestion & Data Pipelines", "k": "Quality Compliance Telco Critical Realistic test data doesn t mean real customer data "}, {"t": "1.17 Null APR in the rates table becomes a 0% quote", "u": "ingestion.html#data-11", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech Critical Missing is not zero "}, {"t": "1.18 Agents compute active subscribers three different ways", "u": "ingestion.html#data-12", "s": "Ingestion & Data Pipelines", "k": "Quality Cost Telco Agents should use the same metric definitions as finance "}, {"t": "1.19 CMS overwrites documents with no version history", "u": "ingestion.html#data-13", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech If the source isn t versioned  your answers can t be defended "}, {"t": "1.20 Ingestion copies EU customer data into a US vector database", "u": "ingestion.html#data-14", "s": "Ingestion & Data Pipelines", "k": "Quality Compliance Telco Personal data stays where it s allowed to live  embeddings included "}, {"t": "1.21 SharePoint permission changes take a week to reach the index", "u": "ingestion.html#data-15", "s": "Ingestion & Data Pipelines", "k": "Quality Security FinTech Revoked access must be revoked everywhere  fast "}, {"t": "1.22 Chunks without product, region or date metadata", "u": "ingestion.html#data-16", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Metadata is what lets retrieval ask  which one  "}, {"t": "1.23 Scraped competitor rates ingested without validation", "u": "ingestion.html#data-17", "s": "Ingestion & Data Pipelines", "k": "Quality FinTech External data needs a label and a sanity check "}, {"t": "1.24 Ingestion job failing silently for three weeks", "u": "ingestion.html#data-18", "s": "Ingestion & Data Pipelines", "k": "Quality Security Telco A pipeline that can fail silently will "}, {"t": "1.25 Deletion job removes AI logs under legal hold", "u": "ingestion.html#data-19", "s": "Ingestion & Data Pipelines", "k": "Quality Compliance FinTech Retention must respect holds  not just deadlines "}, {"t": "1.26 Knowledge articles with no owner go stale", "u": "ingestion.html#data-20", "s": "Ingestion & Data Pipelines", "k": "Quality Telco Every piece of knowledge needs a gardener "}, {"t": "2. Embeddings & Vector Stores", "u": "embeddings.html", "s": "Section"}, {"t": "2.1 One embedding model for every domain and language", "u": "embeddings.html#one-embedding-model", "s": "Embeddings & Vector Stores", "k": "Quality Choose embeddings the way you d choose a database index  by measuring them on the real workload  A leaderboard tells you nothing about the client s part numbers "}, {"t": "2.2 No versioning when the embedding model changes", "u": "embeddings.html#no-embedding-versioning", "s": "Embeddings & Vector Stores", "k": "Reliability Cost Vectors are only comparable inside one model s space  Version the embedder with the index  migrate blue green  and let the eval decide promotion "}, {"t": "2.3 Using the vector database as the system of record", "u": "embeddings.html#vectordb-source-of-truth", "s": "Embeddings & Vector Stores", "k": "Reliability Compliance The vector index should be the cheapest thing to throw away  Keep raw and processed knowledge in governed storage and treat indexes as derived views "}, {"t": "2.4 No access control at retrieval time", "u": "embeddings.html#no-retrieval-acl", "s": "Embeddings & Vector Stores", "k": "Security Compliance Never ask the model to keep secrets  Authorization belongs in the retrieval layer  enforced with the user s own identity before anything enters the prompt "}, {"t": "2.5 Index and query encoded differently (silent recall loss)", "u": "embeddings.html#query-index-encoding-mismatch", "s": "Embeddings & Vector Stores", "k": "Quality Reliability A recall drop with no error is usually an encoding contract mismatch  Share one embedder  test parity in CI  and monitor canary recall "}, {"t": "2.6 Chunks longer than the embedder's input limit", "u": "embeddings.html#chunks-over-embedder-limit", "s": "Embeddings & Vector Stores", "k": "Quality Size chunks in tokens against the embedder s limit  and gate ingestion on it  Silent truncation is a data quality bug  not a model problem "}, {"t": "2.7 Choosing the vector store by hype", "u": "embeddings.html#vector-store-by-hype", "s": "Embeddings & Vector Stores", "k": "Cost Reliability Pick the vector store from requirements  capacity math and a spike on real data  Often the database you already run is enough "}, {"t": "2.8 ANN index defaults never measured", "u": "embeddings.html#ann-defaults-unmeasured", "s": "Embeddings & Vector Stores", "k": "Quality Latency Approximate search is a trade off you should measure  Track ANN recall against exact search and tune to the latency SLO "}, {"t": "2.9 One giant in-memory HNSW index", "u": "embeddings.html#giant-in-memory-index", "s": "Embeddings & Vector Stores", "k": "Reliability Cost Scale At hundreds of millions of vectors  quantize  shard by a natural key and replicate  One giant in memory index is a single point of failure "}, {"t": "2.10 Post-filtering highly selective metadata filters", "u": "embeddings.html#post-filter-selective-metadata", "s": "Embeddings & Vector Stores", "k": "Quality Security Post filtering starves users with narrow permissions  Filter inside the search  partition on selective keys  and use exact search for tiny subsets "}, {"t": "2.11 ACLs copied once at ingest, plus a shared answer cache", "u": "embeddings.html#stale-acls-shared-cache", "s": "Embeddings & Vector Stores", "k": "Security Compliance Permissions change after ingestion and caches cross users  Sync ACLs as events  resolve groups per request  and scope every cache by permission set "}, {"t": "2.12 Noisy neighbours in a shared retrieval cluster", "u": "embeddings.html#noisy-neighbours-shared-cluster", "s": "Embeddings & Vector Stores", "k": "Reliability Latency Scale Isolate ingestion from queries and tenants from each other  Without quotas  one backfill sets everyone s latency "}, {"t": "3. Retrieval & RAG Core", "u": "rag-core.html", "s": "Section"}, {"t": "3.1 Naive top-k vector search with no hybrid retrieval", "u": "rag-core.html#naive-topk", "s": "Retrieval & RAG Core", "k": "Quality Hybrid retrieval is the production baseline  Dense only search fails on precisely the identifiers enterprise users care about most "}, {"t": "3.2 No reranking stage", "u": "rag-core.html#no-reranking", "s": "Retrieval & RAG Core", "k": "Quality Cost Retrieve wide and cheap  rerank narrow and precise  A reranker is usually the highest ROI single upgrade to a RAG system "}, {"t": "3.3 Stuffing the context window (\"lost in the middle\")", "u": "rag-core.html#context-stuffing", "s": "Retrieval & RAG Core", "k": "Quality Cost Latency Context is a budget  not a bucket  Long windows are great for whole document tasks  but retrieval plus ordering plus caching beats stuffing on cost  latency and accuracy "}, {"t": "3.4 No query rewriting or decomposition for multi-hop questions", "u": "rag-core.html#no-query-rewriting", "s": "Retrieval & RAG Core", "k": "Quality Users don t write search queries  they ask compound questions in conversation  Rewrite  decompose and route before you retrieve "}, {"t": "3.5 Answering when retrieval returns nothing relevant", "u": "rag-core.html#answering-without-evidence", "s": "Retrieval & RAG Core", "k": "Quality Compliance  I don t know  here s who does  is a feature  Design and measure abstention instead of letting the model improvise "}, {"t": "3.6 Adding a reranker to fix a recall problem", "u": "rag-core.html#reranker-for-recall-problem", "s": "Retrieval & RAG Core", "k": "Quality Cost A reranker can t promote a chunk that never arrived  Diagnose recall vs precision vs generation before buying a fix "}, {"t": "3.7 Hand-tuned score fusion for hybrid search", "u": "rag-core.html#hand-tuned-score-fusion", "s": "Retrieval & RAG Core", "k": "Quality Reliability Fuse rankings  not raw scores  RRF needs no calibration and doesn t go stale as the corpus changes "}, {"t": "3.8 Reranking without a latency budget", "u": "rag-core.html#rerank-without-latency-budget", "s": "Retrieval & RAG Core", "k": "Latency Quality Every stage needs a latency budget  Optimize the reranker inside its budget instead of choosing between quality and speed "}, {"t": "3.9 Every query gets every query transformation", "u": "rag-core.html#every-transformation-every-query", "s": "Retrieval & RAG Core", "k": "Cost Latency Spend retrieval effort where it changes the answer  Route by difficulty and report cost per correct answer "}, {"t": "3.10 Shipping bundled retrieval upgrades with no ablation", "u": "rag-core.html#retrieval-upgrades-no-ablation", "s": "Retrieval & RAG Core", "k": "Quality Cost If you can t say which change mattered  you can t keep the good ones and drop the expensive ones  Ablate every retrieval change "}, {"t": "3.11 Fixed-size chunking splits the roaming tariff table", "u": "rag-core.html#rag-01", "s": "Retrieval & RAG Core", "k": "Quality Compliance Telco If the BSS already holds a fact as structured data  don t retrieve it from a PDF  Call the system of record  and use RAG only for the explanation around it "}, {"t": "3.12 Vector-only search confuses chargeback reason codes", "u": "rag-core.html#rag-02", "s": "Retrieval & RAG Core", "k": "Quality FinTech Dense for meaning  sparse for identifiers  and fuse both "}, {"t": "3.13 No reranker for broadband troubleshooting articles", "u": "rag-core.html#rag-03", "s": "Retrieval & RAG Core", "k": "Quality Telco Retrieve wide  rerank narrow "}, {"t": "3.14 Stuffing 30 chunks mixes fund share classes", "u": "rag-core.html#rag-04", "s": "Retrieval & RAG Core", "k": "Quality Compliance FinTech Context is a budget  not a bucket "}, {"t": "3.15 Stale index quotes the old savings APY", "u": "rag-core.html#rag-05", "s": "Retrieval & RAG Core", "k": "Quality Compliance FinTech An index is a cache  and every cache needs an invalidation strategy "}, {"t": "3.16 Relationship-manager copilot surfaces a SAR memo", "u": "rag-core.html#rag-06", "s": "Retrieval & RAG Core", "k": "Quality Security Compliance FinTech Critical Enforce permissions in retrieval  never in the prompt "}, {"t": "3.17 Embedding model upgraded without reindexing", "u": "rag-core.html#rag-07", "s": "Retrieval & RAG Core", "k": "Quality Telco Query and document embeddings must come from the same model version "}, {"t": "3.18 Follow-up question retrieved without its history", "u": "rag-core.html#rag-08", "s": "Retrieval & RAG Core", "k": "Quality Telco Retrieve on what the user means  not what they typed "}, {"t": "3.19 Scanned loan agreements parsed as flat text", "u": "rag-core.html#rag-09", "s": "Retrieval & RAG Core", "k": "Quality FinTech Garbage parsing in  confident garbage out "}, {"t": "3.20 Card benefits bot invents trip insurance", "u": "rag-core.html#rag-10", "s": "Retrieval & RAG Core", "k": "Quality FinTech A good RAG system knows when it has nothing to say "}, {"t": "3.21 Early termination fee chunk has no context", "u": "rag-core.html#rag-11", "s": "Retrieval & RAG Core", "k": "Quality Cost Telco Every chunk should make sense on its own "}, {"t": "3.22 RAG used to total quarterly dining spend", "u": "rag-core.html#rag-12", "s": "Retrieval & RAG Core", "k": "Quality Cost FinTech RAG retrieves passages  It can t count "}, {"t": "3.23 Six copies of the SIM activation guide after a merger", "u": "rag-core.html#rag-13", "s": "Retrieval & RAG Core", "k": "Quality Telco Diversity in the top k is a feature "}, {"t": "3.24 Old and new overdraft fee policies both retrieved", "u": "rag-core.html#rag-14", "s": "Retrieval & RAG Core", "k": "Quality FinTech Tell the model which source wins before it has to guess "}, {"t": "3.25 AML policy assistant gives answers with no citations", "u": "rag-core.html#rag-15", "s": "Retrieval & RAG Core", "k": "Quality Compliance FinTech Citations make answers checkable and failures debuggable "}, {"t": "3.26 KB migration drops quality and nobody can localize it", "u": "rag-core.html#rag-16", "s": "Retrieval & RAG Core", "k": "Quality Cost Telco Evaluate the retriever and the generator separately "}, {"t": "3.27 Multi-hop question about maintenance and SLA penalties", "u": "rag-core.html#rag-17", "s": "Retrieval & RAG Core", "k": "Quality Telco Some questions need a plan  not a search "}, {"t": "3.28 Fraud-call agent assist too slow to use", "u": "rag-core.html#rag-18", "s": "Retrieval & RAG Core", "k": "Quality Cost Latency FinTech Budget latency per stage  and parallelize what doesn t depend on each other "}, {"t": "3.29 Merchant evidence PDF carries a hidden instruction", "u": "rag-core.html#rag-19", "s": "Retrieval & RAG Core", "k": "Quality Security FinTech Critical Every retrieved or uploaded document is user input "}, {"t": "3.30 Spanish questions miss Spanish knowledge articles", "u": "rag-core.html#rag-20", "s": "Retrieval & RAG Core", "k": "Quality Telco Evaluate per language  not on average "}, {"t": "4. Advanced RAG & Fine-tuning vs RAG", "u": "advanced-rag.html", "s": "Section"}, {"t": "4.1 GraphRAG or agentic RAG where simple RAG works", "u": "advanced-rag.html#overengineered-rag", "s": "Advanced RAG", "k": "Cost Latency Reliability Advanced RAG is a tool  not a maturity level  Profile the queries  default to simple  and escalate only for the segments that measurably need it "}, {"t": "4.2 No citation or grounding verification", "u": "advanced-rag.html#no-citation-verification", "s": "Advanced RAG", "k": "Quality Compliance A citation nobody verified is decoration  Make citations structured  check them claim by claim  and measure faithfulness "}, {"t": "4.3 Ignoring temporal freshness and document validity", "u": "advanced-rag.html#temporal-blindness", "s": "Advanced RAG", "k": "Quality Compliance  Correct  is time dependent  Index validity dates  resolve the question s time frame  and filter before ranking "}, {"t": "4.4 Using RAG to fix behaviour, or fine-tuning to add knowledge", "u": "advanced-rag.html#rag-vs-finetune-confusion", "s": "Advanced RAG", "k": "Cost Quality RAG and tools for knowledge  prompting or fine tuning for behaviour  Mixing them up produces stale facts or bloated prompts "}, {"t": "4.5 Contextual chunking rolled out without a cost model", "u": "advanced-rag.html#contextual-chunking-no-cost-model", "s": "Advanced RAG", "k": "Cost Quality Good retrieval techniques still need a budget  Price per chunk enrichment  start where retrieval is worst  and skip unchanged chunks "}, {"t": "4.6 Fine-tuning a model to answer credit-card policy questions", "u": "advanced-rag.html#ft-01", "s": "Advanced RAG", "k": "Quality FinTech Fine tune for how to say it  Retrieve what to say "}, {"t": "4.7 Adding more retrieval to fix the bot's tone", "u": "advanced-rag.html#ft-02", "s": "Advanced RAG", "k": "Quality Telco Retrieval fixes what the model knows  not how it talks "}, {"t": "4.8 Prompt with 400 ticket categories for routing", "u": "advanced-rag.html#ft-03", "s": "Advanced RAG", "k": "Quality Cost Telco Lots of labels plus lots of data means train  don t prompt "}, {"t": "4.9 Fine-tuned model shipped without a held-out evaluation", "u": "advanced-rag.html#ft-04", "s": "Advanced RAG", "k": "Quality FinTech A fine tune must beat the baseline on held out data  or it doesn t ship "}, {"t": "4.10 Fine-tuning on the bot's own past answers", "u": "advanced-rag.html#ft-05", "s": "Advanced RAG", "k": "Quality Cost Latency Telco Don t teach a model its own mistakes "}, {"t": "4.11 Fine-tune makes the model forget its refusals", "u": "advanced-rag.html#ft-06", "s": "Advanced RAG", "k": "Quality FinTech Fine tuning can unlearn safety  Re test it every time "}, {"t": "4.12 Fine-tuning teaches a confident tone, not correct answers", "u": "advanced-rag.html#ft-07", "s": "Advanced RAG", "k": "Quality Telco Confidence should come from evidence  not training "}, {"t": "4.13 Fifty examples expected to teach a complex task", "u": "advanced-rag.html#ft-08", "s": "Advanced RAG", "k": "Quality FinTech Fine tuning needs data  Measure the learning curve first "}, {"t": "4.14 Fine-tuned model's base version is being retired", "u": "advanced-rag.html#ft-09", "s": "Advanced RAG", "k": "Quality Telco A fine tune is a pipeline  not an artifact "}, {"t": "4.15 Fine-tuned model repeats customers' account numbers", "u": "advanced-rag.html#ft-10", "s": "Advanced RAG", "k": "Quality Security FinTech Critical Whatever goes into training can come out in answers "}, {"t": "4.16 Twenty thousand documents stuffed into long context", "u": "advanced-rag.html#ft-11", "s": "Advanced RAG", "k": "Quality Telco Long context complements retrieval  It doesn t replace it "}, {"t": "4.17 RAG over documents to trace beneficial ownership", "u": "advanced-rag.html#ft-12", "s": "Advanced RAG", "k": "Quality Compliance FinTech Relationships need a graph  Arithmetic needs code "}, {"t": "4.18 Small model distilled from a provider's outputs against its terms", "u": "advanced-rag.html#ft-13", "s": "Advanced RAG", "k": "Quality Cost Telco Check the licence before you distil "}, {"t": "4.19 Prompt change and fine-tune shipped together", "u": "advanced-rag.html#ft-14", "s": "Advanced RAG", "k": "Quality FinTech Change one thing  or run the ablation "}, {"t": "4.20 Fine-tuning chosen because a competitor announced it", "u": "advanced-rag.html#ft-15", "s": "Advanced RAG", "k": "Quality Telco Let the error analysis pick the technique "}, {"t": "4.21 Fine-tuned model can't show where its answers come from", "u": "advanced-rag.html#ft-16", "s": "Advanced RAG", "k": "Quality Compliance FinTech If you need sources  you need retrieval "}, {"t": "4.22 Generic embeddings don't understand telco jargon", "u": "advanced-rag.html#ft-17", "s": "Advanced RAG", "k": "Quality Telco Sometimes the thing to fine tune is the retriever "}, {"t": "4.23 Fine-tuned on synthetic disputes, fails on real ones", "u": "advanced-rag.html#ft-18", "s": "Advanced RAG", "k": "Quality FinTech Synthetic data must look like the real world  and be tested on it "}, {"t": "4.24 Fine-tune saves on tokens, costs more to host", "u": "advanced-rag.html#ft-19", "s": "Advanced RAG", "k": "Quality Cost Telco Count the whole cost  not just the tokens "}, {"t": "4.25 Fine-tuned model never A/B tested against the old one", "u": "advanced-rag.html#ft-20", "s": "Advanced RAG", "k": "Quality FinTech A model change is an experiment  Run it like one "}, {"t": "5. Prompt Engineering & Management", "u": "prompts.html", "s": "Section"}, {"t": "5.1 Prompts hardcoded in application code with no versioning", "u": "prompts.html#hardcoded-prompts", "s": "Prompt Engineering", "k": "Reliability Quality If a prompt can change a business decision  it needs version control  an eval gate and a trace ID  just like code "}, {"t": "5.2 The mega-prompt that does everything", "u": "prompts.html#mega-prompt", "s": "Prompt Engineering", "k": "Quality Cost Reliability One prompt per job  composed by code  Mega prompts are the monoliths of LLM applications "}, {"t": "5.3 Parsing free-text output with regex", "u": "prompts.html#freetext-parsing", "s": "Prompt Engineering", "k": "Reliability Don t parse prose  Ask for typed output with native structured output modes  then validate the business rules as well as the schema "}, {"t": "5.4 Relying on prompt instructions alone for safety and policy", "u": "prompts.html#prompt-only-safety", "s": "Prompt Engineering", "k": "Security Compliance A system prompt is a request  not a control  Safety needs layered  deterministic guards with logs that an auditor can test "}, {"t": "5.5 Care-bot prompts scattered through the codebase", "u": "prompts.html#prm-01", "s": "Prompt Engineering", "k": "Quality Telco Prompts are config with a test suite "}, {"t": "5.6 Adding be empathetic makes the collections bot promise payment plans", "u": "prompts.html#prm-02", "s": "Prompt Engineering", "k": "Quality FinTech Every prompt fix is a potential regression "}, {"t": "5.7 Nine thousand tokens of contradictory rules", "u": "prompts.html#prm-03", "s": "Prompt Engineering", "k": "Quality Telco Refactor prompts like code  Delete dead rules "}, {"t": "5.8 NEVER GIVE FINANCIAL ADVICE makes the bot refuse to explain APR", "u": "prompts.html#prm-04", "s": "Prompt Engineering", "k": "Quality Compliance FinTech Explain the reason  and the model generalises correctly "}, {"t": "5.9 Don't use jargon produces vague router instructions", "u": "prompts.html#prm-05", "s": "Prompt Engineering", "k": "Quality Telco Say what you want  not only what you don t "}, {"t": "5.10 Transaction categories parsed from prose with regex", "u": "prompts.html#prm-06", "s": "Prompt Engineering", "k": "Quality Cost FinTech Use structured output APIs  not regex hope "}, {"t": "5.11 Summarise this ticket gives one line or three paragraphs", "u": "prompts.html#prm-07", "s": "Prompt Engineering", "k": "Quality Telco Write the prompt as a brief for a smart new hire "}, {"t": "5.12 One prompt classifies, extracts, computes redress and drafts the reply", "u": "prompts.html#prm-08", "s": "Prompt Engineering", "k": "Quality FinTech Decompose before you optimise "}, {"t": "5.13 Model migration drops quality 15% with the same prompts", "u": "prompts.html#prm-09", "s": "Prompt Engineering", "k": "Quality Cost Telco Prompts are tuned to a model  so migration means re tuning "}, {"t": "5.14 AML alert disposition written before its rationale", "u": "prompts.html#prm-10", "s": "Prompt Engineering", "k": "Quality Compliance FinTech Think  then answer  Not the other way around "}, {"t": "5.15 Every device description starts with Introducing", "u": "prompts.html#prm-11", "s": "Prompt Engineering", "k": "Quality Telco Models copy examples  so vary them "}, {"t": "5.16 Ignore the above prints internal fee-waiver codes", "u": "prompts.html#prm-12", "s": "Prompt Engineering", "k": "Quality Security FinTech Assume the system prompt will leak  Put no secrets in it "}, {"t": "5.17 Port-in form extraction differs between runs", "u": "prompts.html#prm-13", "s": "Prompt Engineering", "k": "Quality Telco Sampling parameters are part of the prompt "}, {"t": "5.18 You are a world-class tax attorney doesn't improve accuracy", "u": "prompts.html#prm-14", "s": "Prompt Engineering", "k": "Quality FinTech Context beats persona "}, {"t": "5.19 SIM registration extractor invents an ID number from a blurry photo", "u": "prompts.html#prm-15", "s": "Prompt Engineering", "k": "Quality Telco Give the model a legal way to say I don t know "}, {"t": "5.20 Max fee waiver of $25 in the prompt, $100 in practice", "u": "prompts.html#prm-16", "s": "Prompt Engineering", "k": "Quality FinTech Prompts guide  Code enforces "}, {"t": "5.21 A magic prompt template adds 800 tokens and no gain", "u": "prompts.html#prm-17", "s": "Prompt Engineering", "k": "Quality Cost Telco Every token in the prompt should earn its place "}, {"t": "5.22 French-Canadian customers get English replies and US date formats", "u": "prompts.html#prm-18", "s": "Prompt Engineering", "k": "Quality FinTech Make locale an explicit input "}, {"t": "5.23 Hello {customer_name} reaches customers", "u": "prompts.html#prm-19", "s": "Prompt Engineering", "k": "Quality Telco Test the template rendering  not just the model "}, {"t": "5.24 Weeks of hand-tuning for a 1% gain", "u": "prompts.html#prm-20", "s": "Prompt Engineering", "k": "Quality Cost FinTech When hand tuning plateaus  optimise systematically or change the approach "}, {"t": "6. Model Selection, Cost, Latency & Routing", "u": "models.html", "s": "Section"}, {"t": "6.1 One frontier model for every task", "u": "models.html#one-model-for-all", "s": "Models, Cost & Latency", "k": "Cost Latency Treat models like a portfolio  Route each task to the cheapest model that passes its eval  and escalate only when needed "}, {"t": "6.2 No fallback or multi-provider strategy", "u": "models.html#single-provider-no-fallback", "s": "Models, Cost & Latency", "k": "Reliability Models are external dependencies with SLAs  Engineer them like payment gateways  with failover  circuit breakers and a degraded mode "}, {"t": "6.3 Fine-tuning too early", "u": "models.html#premature-finetuning", "s": "Models, Cost & Latency", "k": "Cost Quality Fine tuning is the last rung of the ladder  not the first  Exhaust prompting  examples and retrieval against a baseline before you buy a model lifecycle "}, {"t": "6.4 Ignoring latency budgets and serving modes", "u": "models.html#ignoring-latency-budget", "s": "Models, Cost & Latency", "k": "Latency Cost Latency is a design constraint  not a tuning afterthought  Budget it per step  stream  parallelize  cache  and batch whatever isn t interactive "}, {"t": "6.5 Retrying failed LLM calls with full context and no budget", "u": "models.html#retry-cost-explosion", "s": "Models, Cost & Latency", "k": "Cost Reliability Critical Retries must be cheaper  rarer and bounded  and every model call must have an owner and a budget  Put retries in one gateway with a circuit breaker  cap spend at every level  and check cost per succes"}, {"t": "6.6 No one knows what a resolved card dispute costs", "u": "models.html#cost-01", "s": "Models, Cost & Latency", "k": "Cost FinTech Know the cost of a success  per intent "}, {"t": "6.7 Router sends hard complaints to the small model", "u": "models.html#cost-02", "s": "Models, Cost & Latency", "k": "Cost FinTech Route by risk and intent  not by message length "}, {"t": "6.8 Voice agent pauses for 3 seconds before every reply", "u": "models.html#cost-03", "s": "Models, Cost & Latency", "k": "Cost Latency Telco In voice  latency is the user experience "}, {"t": "6.9 Fifteen-thousand-token system prompt for a balance question", "u": "models.html#cost-04", "s": "Models, Cost & Latency", "k": "Cost Latency FinTech Load instructions for the job at hand "}, {"t": "6.10 Prompt caching enabled, but the cache expires between turns", "u": "models.html#cost-05", "s": "Models, Cost & Latency", "k": "Cost Telco Know how your cache expires before you count the savings "}, {"t": "6.11 Semantic cache confuses cancel my card with cancel my card payment", "u": "models.html#cost-06", "s": "Models, Cost & Latency", "k": "Cost FinTech Similar isn t the same  Key the cache by intent "}, {"t": "6.12 One conversation costs $40", "u": "models.html#cost-07", "s": "Models, Cost & Latency", "k": "Cost Telco Budget each conversation  not just the month "}, {"t": "6.13 Replies three times longer than customers need", "u": "models.html#cost-08", "s": "Models, Cost & Latency", "k": "Cost FinTech Shorter answers are cheaper and usually better "}, {"t": "6.14 Nightly ticket summaries run on the real-time API", "u": "models.html#cost-09", "s": "Models, Cost & Latency", "k": "Cost Telco If it can wait  batch it "}, {"t": "6.15 Extended reasoning turned on for every request", "u": "models.html#cost-10", "s": "Models, Cost & Latency", "k": "Cost Latency FinTech Pay for thinking where thinking pays "}, {"t": "6.16 Customers stare at a spinner for 8 seconds", "u": "models.html#cost-11", "s": "Models, Cost & Latency", "k": "Cost Latency Telco Show progress  Silence feels slower than it is "}, {"t": "6.17 Independent lookups run one after another", "u": "models.html#cost-12", "s": "Models, Cost & Latency", "k": "Cost Latency FinTech Parallelise what doesn t depend on each other "}, {"t": "6.18 Speculative prefetching that's mostly wasted", "u": "models.html#cost-13", "s": "Models, Cost & Latency", "k": "Cost Latency Telco Prefetch what you ll probably use  not everything you might "}, {"t": "6.19 Large model classifying 100 million transactions a month", "u": "models.html#cost-14", "s": "Models, Cost & Latency", "k": "Cost FinTech High volume and narrow scope means small model "}, {"t": "6.20 Retry storm doubles cost during a provider incident", "u": "models.html#cost-15", "s": "Models, Cost & Latency", "k": "Cost Latency Telco Retry in one place  with backoff and a budget "}, {"t": "6.21 Embeddings recomputed for unchanged documents every night", "u": "models.html#cost-16", "s": "Models, Cost & Latency", "k": "Cost FinTech Embed what changed "}, {"t": "6.22 AI costs land in one central budget", "u": "models.html#cost-17", "s": "Models, Cost & Latency", "k": "Cost Telco Whoever drives the cost should see the cost "}, {"t": "6.23 Self-hosted GPUs sit idle 80% of the day", "u": "models.html#cost-18", "s": "Models, Cost & Latency", "k": "Cost FinTech Idle GPUs are the most expensive tokens "}, {"t": "6.24 Latency SLO with no plan for when it's missed", "u": "models.html#cost-19", "s": "Models, Cost & Latency", "k": "Cost Latency Telco When you miss the budget  degrade  Don t wait "}, {"t": "6.25 Prompt compression saves tokens and drops the disclosures", "u": "models.html#cost-20", "s": "Models, Cost & Latency", "k": "Cost Compliance FinTech A saving that breaks compliance isn t a saving "}, {"t": "7. Agent Design, Frameworks & Tool Use", "u": "agents.html", "s": "Section"}, {"t": "7.1 Building an agent where a deterministic workflow would do", "u": "agents.html#agent-for-workflow", "s": "Agent Design & Frameworks", "k": "Reliability Cost Start with the least autonomy that solves the problem  Agents are for unknown paths  not for running a process you already know "}, {"t": "7.2 Too many tools with vague descriptions", "u": "agents.html#tool-sprawl", "s": "Agent Design & Frameworks", "k": "Quality Cost Tools are a model facing API  Curate them  describe them like documentation  constrain their schemas  and load them on demand "}, {"t": "7.3 Tools with no input validation, idempotency or blast-radius limits", "u": "agents.html#unvalidated-tools", "s": "Agent Design & Frameworks", "k": "Security Reliability Treat every model generated argument as untrusted input  Validate it  bound it  make it idempotent  and require approval above a risk threshold "}, {"t": "7.4 Unbounded loops with no step, time or cost budget", "u": "agents.html#unbounded-loops", "s": "Agent Design & Frameworks", "k": "Cost Reliability An agent without a budget is an open ended cost commitment  Cap steps  tokens  time and money  detect stalls  and exit gracefully "}, {"t": "7.5 No state persistence or checkpointing", "u": "agents.html#no-checkpointing", "s": "Agent Design & Frameworks", "k": "Reliability Long running agents are workflows  Give them durable state  interrupts for humans  and replayable history "}, {"t": "7.6 Port-in processing built as a free-roaming agent", "u": "agents.html#agf-01", "s": "Agent Design & Frameworks", "k": "Reliability Telco Autonomy is a cost  so spend it only where the path is unknown "}, {"t": "7.7 Reconciliation agent loops all night on one break", "u": "agents.html#agf-02", "s": "Agent Design & Frameworks", "k": "Reliability Cost FinTech Every loop needs a circuit breaker "}, {"t": "7.8 Care agent exposed to 60 BSS APIs", "u": "agents.html#agf-03", "s": "Agent Design & Frameworks", "k": "Reliability Cost Telco Tool choice degrades as the toolbox grows "}, {"t": "7.9 Payment tool amount in cents read as dollars", "u": "agents.html#agf-04", "s": "Agent Design & Frameworks", "k": "Reliability FinTech Critical Tool descriptions are prompts  so engineer them "}, {"t": "7.10 Care agent issues a $400 goodwill credit on its own", "u": "agents.html#agf-05", "s": "Agent Design & Frameworks", "k": "Reliability Telco Put the guardrail in the tool  not the prompt "}, {"t": "7.11 Retry after timeout sends a wire twice", "u": "agents.html#agf-06", "s": "Agent Design & Frameworks", "k": "Reliability Latency FinTech Critical Assume every tool call might run twice "}, {"t": "7.12 B2B order agent loses state on a pod restart", "u": "agents.html#agf-07", "s": "Agent Design & Frameworks", "k": "Reliability Telco Long running agents need durable execution "}, {"t": "7.13 Five agents for a loan pre-qualification", "u": "agents.html#agf-08", "s": "Agent Design & Frameworks", "k": "Reliability Cost Latency FinTech Add agents to solve a measured problem  not for the diagram "}, {"t": "7.14 Framework default prompt overrides the brand voice", "u": "agents.html#agf-09", "s": "Agent Design & Frameworks", "k": "Reliability Cost Security Telco Always know exactly what goes to the model "}, {"t": "7.15 80 KB of usage records dumped into the agent context", "u": "agents.html#agf-10", "s": "Agent Design & Frameworks", "k": "Reliability Cost Telco Tools should return answers  not data dumps "}, {"t": "7.16 Agent retries an opaque KYC vendor error ten times", "u": "agents.html#agf-11", "s": "Agent Design & Frameworks", "k": "Reliability Compliance FinTech Error messages are instructions for the next step "}, {"t": "7.17 Care agent runs with an admin BSS service account", "u": "agents.html#agf-12", "s": "Agent Design & Frameworks", "k": "Reliability Security Telco Critical An agent should never have more access than the user it serves "}, {"t": "7.18 Account-closure plan ignores pending transactions", "u": "agents.html#agf-13", "s": "Agent Design & Frameworks", "k": "Reliability FinTech Plans are hypotheses  so update them on evidence "}, {"t": "7.19 Diagnosis agent tells the dispatch agent to see above", "u": "agents.html#agf-14", "s": "Agent Design & Frameworks", "k": "Reliability Telco Agent handoffs need API contracts "}, {"t": "7.20 Mortgage document agent runs inside a 30-second HTTP call", "u": "agents.html#agf-15", "s": "Agent Design & Frameworks", "k": "Reliability Cost Latency FinTech Agents are jobs  not requests "}, {"t": "7.21 Provider outage takes the care bot down at bill-run time", "u": "agents.html#agf-16", "s": "Agent Design & Frameworks", "k": "Reliability Telco Design for the model being unavailable "}, {"t": "7.22 Agent computes a loan payoff and gets daily interest wrong", "u": "agents.html#agf-17", "s": "Agent Design & Frameworks", "k": "Reliability FinTech Use the LLM for judgement and code for arithmetic "}, {"t": "7.23 Three-hour troubleshooting session forgets the original fault", "u": "agents.html#agf-18", "s": "Agent Design & Frameworks", "k": "Reliability Telco Memory needs a retention policy "}, {"t": "7.24 Pay John sends money to the wrong John", "u": "agents.html#agf-19", "s": "Agent Design & Frameworks", "k": "Reliability FinTech Critical Asking is a valid action "}, {"t": "7.25 Frontier model used for every care-flow step", "u": "agents.html#agf-20", "s": "Agent Design & Frameworks", "k": "Reliability Cost Telco Match the model to the step "}, {"t": "8. Multi-Agent Systems", "u": "multi-agent.html", "s": "Section"}, {"t": "8.1 Multi-agent for its own sake (\"the org chart in code\")", "u": "multi-agent.html#org-chart-agents", "s": "Multi-Agent Systems", "k": "Cost Reliability Agents aren t headcount  Add one only for parallelism  context isolation or privilege separation  and prove it beats the single agent baseline "}, {"t": "8.2 Chatty agents passing full transcripts", "u": "multi-agent.html#chatty-agents", "s": "Multi-Agent Systems", "k": "Cost Latency Agents should exchange contracts  not conversations  Use typed hand offs  pass artifacts by reference  and throw away scratch work "}, {"t": "8.3 No supervisor, contract or termination condition", "u": "multi-agent.html#no-supervisor", "s": "Multi-Agent Systems", "k": "Reliability Every multi agent system needs an owner of  done   a supervisor  acceptance criteria and a revision limit "}, {"t": "8.4 Shared mutable memory without concurrency control", "u": "multi-agent.html#shared-mutable-memory", "s": "Multi-Agent Systems", "k": "Reliability Shared agent memory is a concurrency problem  Scope it  append rather than overwrite  version mutable records  and attribute every write "}, {"t": "8.5 Cascading failures with no circuit breakers", "u": "multi-agent.html#cascading-failures", "s": "Multi-Agent Systems", "k": "Reliability Cost Agent pipelines need the resilience patterns of distributed systems  contract checks  circuit breakers and staged writes "}, {"t": "8.6 Sub-agents with vague briefs", "u": "multi-agent.html#subagents-vague-briefs", "s": "Multi-Agent Systems", "k": "Quality Cost Sub agents are only as good as their briefs  Give each a scoped objective  tools and an output schema  then merge and verify centrally "}, {"t": "8.7 Supervisor agent becomes the bottleneck for every request", "u": "multi-agent.html#mas-01", "s": "Multi-Agent Systems", "k": "Reliability Latency FinTech Route simple work  Supervise only complex work "}, {"t": "8.8 Planner and critic agents debate for 40 rounds", "u": "multi-agent.html#mas-02", "s": "Multi-Agent Systems", "k": "Reliability Cost Telco Reflection has diminishing returns  Cap it "}, {"t": "8.9 Two agents update the same fraud case at once", "u": "multi-agent.html#mas-03", "s": "Multi-Agent Systems", "k": "Reliability FinTech Shared state needs an owner and a version number "}, {"t": "8.10 Facts lost in a chain of agent summaries", "u": "multi-agent.html#mas-04", "s": "Multi-Agent Systems", "k": "Reliability Telco Pass facts as data  not as retellings "}, {"t": "8.11 Three agents message the customer at once", "u": "multi-agent.html#mas-05", "s": "Multi-Agent Systems", "k": "Reliability FinTech One voice per customer "}, {"t": "8.12 Agents delegate a task back and forth", "u": "multi-agent.html#mas-06", "s": "Multi-Agent Systems", "k": "Reliability Latency Telco Every task needs an owner when nobody else wants it "}, {"t": "8.13 Maker and checker agents share the same permissions and model", "u": "multi-agent.html#mas-07", "s": "Multi-Agent Systems", "k": "Reliability Security FinTech Two copies of the same agent aren t dual control "}, {"t": "8.14 Two parallel agents provision the same line", "u": "multi-agent.html#mas-08", "s": "Multi-Agent Systems", "k": "Reliability Telco Parallelise independent work only "}, {"t": "8.15 Each agent has a budget, the system has none", "u": "multi-agent.html#mas-09", "s": "Multi-Agent Systems", "k": "Reliability Cost FinTech Budgets belong to the task  not the worker "}, {"t": "8.16 Customer asked to verify identity again after every handoff", "u": "multi-agent.html#mas-10", "s": "Multi-Agent Systems", "k": "Reliability Telco Hand off the context  not just the conversation "}, {"t": "8.17 Reviewer agent approves its sibling's credit memos", "u": "multi-agent.html#mas-11", "s": "Multi-Agent Systems", "k": "Reliability FinTech A reviewer that can t see the source is just a second opinion on prose "}, {"t": "8.18 Partner carrier's agent sends instructions the agent follows", "u": "multi-agent.html#mas-12", "s": "Multi-Agent Systems", "k": "Reliability Telco Critical Another company s agent is another company s input "}, {"t": "8.19 Collections agent and hardship agent contradict each other", "u": "multi-agent.html#mas-13", "s": "Multi-Agent Systems", "k": "Reliability FinTech Agents need shared rules  not just shared data "}, {"t": "8.20 Debugging a multi-agent failure from six separate logs", "u": "multi-agent.html#mas-14", "s": "Multi-Agent Systems", "k": "Reliability Cost Telco Multi agent without tracing is multi mystery "}, {"t": "8.21 Thirty agents and nobody knows who owns which", "u": "multi-agent.html#mas-15", "s": "Multi-Agent Systems", "k": "Reliability Security Compliance FinTech Every agent needs an owner and an identity "}, {"t": "8.22 Five levels of sub-agents add 30 seconds", "u": "multi-agent.html#mas-16", "s": "Multi-Agent Systems", "k": "Reliability Latency Telco Architect for the task  not the org chart "}, {"t": "8.23 Majority vote of three identical agents", "u": "multi-agent.html#mas-17", "s": "Multi-Agent Systems", "k": "Reliability Cost FinTech Copies agree  That s not confidence "}, {"t": "8.24 Group chat of agents with no end condition", "u": "multi-agent.html#mas-18", "s": "Multi-Agent Systems", "k": "Reliability Telco Agents need an agenda and a chair "}, {"t": "8.25 One failing agent takes down the whole onboarding flow", "u": "multi-agent.html#mas-19", "s": "Multi-Agent Systems", "k": "Reliability FinTech One agent s outage shouldn t be everyone s outage "}, {"t": "8.26 Only the orchestrator's final answer is evaluated", "u": "multi-agent.html#mas-20", "s": "Multi-Agent Systems", "k": "Reliability Cost Telco Evaluate every agent  not just the team score "}, {"t": "9. Memory & Context Engineering", "u": "memory.html", "s": "Section"}, {"t": "9.1 Dumping the full chat history into every call", "u": "memory.html#full-history-dump", "s": "Memory & Context", "k": "Cost Quality Latency Context is assembled  not accumulated  Pin the essentials  keep recent turns  compact the rest  and retrieve on demand "}, {"t": "9.2 No separation of short-term, long-term and procedural memory", "u": "memory.html#undifferentiated-memory", "s": "Memory & Context", "k": "Quality Compliance Memory isn t one thing  Type it  scope it and give each type its own lifetime and trust level "}, {"t": "9.3 Unverified memory writes (memory poisoning)", "u": "memory.html#memory-poisoning", "s": "Memory & Context", "k": "Security Quality Memory can inform an agent but never authorize it  Verify  scope and expire memory writes  and keep permissions in systems of record "}, {"t": "9.4 No forgetting or retention policy", "u": "memory.html#no-forgetting", "s": "Memory & Context", "k": "Compliance Every copy of personal data in the AI stack counts  Inventory the stores  key them by data subject  and automate retention and erasure "}, {"t": "9.5 Whole credit agreement and two years of statements in one prompt", "u": "memory.html#ctx-01", "s": "Memory & Context", "k": "Quality Cost Latency FinTech The smallest context that contains the answer wins "}, {"t": "9.6 At step 40 the agent forgets the change-window constraint", "u": "memory.html#ctx-02", "s": "Memory & Context", "k": "Quality Telco Compact the history  pin the goal "}, {"t": "9.7 Card-number rule buried among 8,000 tokens of policy", "u": "memory.html#ctx-03", "s": "Memory & Context", "k": "Quality FinTech Position is part of the prompt "}, {"t": "9.8 Customer email instruction changes the ticket agent's behaviour", "u": "memory.html#ctx-04", "s": "Memory & Context", "k": "Quality Security Telco Label data as data "}, {"t": "9.9 Intent classifier receives 20k tokens it doesn't need", "u": "memory.html#ctx-05", "s": "Memory & Context", "k": "Quality Cost Latency FinTech Each call gets the context its job needs "}, {"t": "9.10 Timestamp at the top kills prompt caching", "u": "memory.html#ctx-06", "s": "Memory & Context", "k": "Quality Cost Telco Static first  dynamic last  for cache hits "}, {"t": "9.11 Chat history squeezes out the retrieved fee schedule", "u": "memory.html#ctx-07", "s": "Memory & Context", "k": "Quality Cost FinTech Budget the window like memory in an embedded system "}, {"t": "9.12 Second half of a 300-page MSA silently truncated", "u": "memory.html#ctx-08", "s": "Memory & Context", "k": "Quality Telco Never truncate without saying so "}, {"t": "9.13 Wealth assistant brings up a client's divorce in a portfolio review", "u": "memory.html#ctx-09", "s": "Memory & Context", "k": "Quality FinTech Memory needs writing rules  not just storage "}, {"t": "9.14 Device ships to the old address", "u": "memory.html#ctx-10", "s": "Memory & Context", "k": "Quality Telco Memory is a database  so it needs updates  not just inserts "}, {"t": "9.15 Forty-five tool schemas use 18k tokens before the customer speaks", "u": "memory.html#ctx-11", "s": "Memory & Context", "k": "Quality Cost FinTech Tools are context  so load them on demand "}, {"t": "9.16 Half-finished trade-in restarts the next day", "u": "memory.html#ctx-12", "s": "Memory & Context", "k": "Quality Telco Keep task state in a store  not in the transcript "}, {"t": "9.17 Full SEC filing HTML sent to answer a dividend question", "u": "memory.html#ctx-13", "s": "Memory & Context", "k": "Quality FinTech Clean the context before you send it "}, {"t": "9.18 Retrieved text with no source or date", "u": "memory.html#ctx-14", "s": "Memory & Context", "k": "Quality Telco Context without provenance can t be cited "}, {"t": "9.19 Compaction drops that the account needs two signatures", "u": "memory.html#ctx-15", "s": "Memory & Context", "k": "Quality FinTech Compaction is lossy  so choose what it may lose "}, {"t": "9.20 Five sub-agents each receive the full 100k context", "u": "memory.html#ctx-16", "s": "Memory & Context", "k": "Quality Cost Telco Sub agents get a brief  not a transcript "}, {"t": "9.21 Semantic cache serves one customer's balance to another", "u": "memory.html#ctx-17", "s": "Memory & Context", "k": "Quality Cost FinTech Critical Context isolation is a security boundary "}, {"t": "9.22 Refund examples copied into shipping answers", "u": "memory.html#ctx-18", "s": "Memory & Context", "k": "Quality Telco Examples are context  so retrieve the relevant ones "}, {"t": "9.23 Engineers argue about what the model saw", "u": "memory.html#ctx-19", "s": "Memory & Context", "k": "Quality FinTech If you can t see the context  you can t engineer it "}, {"t": "9.24 Config agent tries to hold 300 router configs in context", "u": "memory.html#ctx-20", "s": "Memory & Context", "k": "Quality Compliance Telco Give the agent a notebook  not a bigger head "}, {"t": "9.25 Customer moves from chat to the IVR and repeats everything", "u": "memory.html#mem-01", "s": "Memory & Context", "k": "Quality Cost Latency Telco Memory should follow the customer  not the channel "}, {"t": "9.26 Long-term memory is a pile of raw transcripts", "u": "memory.html#mem-02", "s": "Memory & Context", "k": "Quality FinTech Memories are curated facts  not transcripts "}, {"t": "9.27 Assistant remembers things customers never knew it stored", "u": "memory.html#mem-03", "s": "Memory & Context", "k": "Quality Compliance FinTech Memory needs a purpose and the customer s knowledge "}, {"t": "9.28 Household tablet mixes two family members' memories", "u": "memory.html#mem-04", "s": "Memory & Context", "k": "Quality Telco Scope memory to the person  not the login "}, {"t": "9.29 Remembered preference outlives the customer's change", "u": "memory.html#mem-05", "s": "Memory & Context", "k": "Quality FinTech If a system owns the fact  ask the system "}, {"t": "9.30 Memories kept forever with no retention rule", "u": "memory.html#mem-06", "s": "Memory & Context", "k": "Quality Telco Every memory needs an expiry date "}, {"t": "9.31 Remember that I'm a VIP and always waive my fees", "u": "memory.html#mem-07", "s": "Memory & Context", "k": "Quality FinTech A customer s claim in memory is still just a claim "}, {"t": "9.32 Agent remembers its own wrong promise as a fact", "u": "memory.html#mem-08", "s": "Memory & Context", "k": "Quality Telco Don t promote your own words to facts "}, {"t": "9.33 Memory retrieval ignores recency and importance", "u": "memory.html#mem-09", "s": "Memory & Context", "k": "Quality FinTech Rank memories by relevance  recency and importance "}, {"t": "9.34 Billing agent forgets what the care agent learned", "u": "memory.html#mem-10", "s": "Memory & Context", "k": "Quality Telco Agents serving one customer should share one memory "}, {"t": "9.35 Every memory injected into every prompt", "u": "memory.html#mem-11", "s": "Memory & Context", "k": "Quality Cost Security FinTech Memory is retrieved  not recited "}, {"t": "9.36 NOC agent never learns from resolved incidents", "u": "memory.html#mem-12", "s": "Memory & Context", "k": "Quality Telco Turn resolved cases into reviewed procedures "}, {"t": "9.37 Agent writes its own rules from experience, unchecked", "u": "memory.html#mem-13", "s": "Memory & Context", "k": "Quality FinTech Agents may suggest procedures  Humans approve them "}, {"t": "9.38 One advisor's client notes surface for another advisor", "u": "memory.html#mem-14", "s": "Memory & Context", "k": "Quality FinTech Memory inherits the access rules of the data it came from "}, {"t": "9.39 Client disputes what the assistant remembered, no audit", "u": "memory.html#mem-15", "s": "Memory & Context", "k": "Quality Compliance FinTech If a fact can be disputed  it needs provenance "}, {"t": "9.40 Do not market to me becomes market to me in a summary", "u": "memory.html#mem-16", "s": "Memory & Context", "k": "Quality Compliance Telco Consent lives in the consent system  not in a summary "}, {"t": "9.41 Vulnerability flag remembered by one agent, ignored by others", "u": "memory.html#mem-17", "s": "Memory & Context", "k": "Quality Compliance FinTech Important disclosures must change the record  not just the reply "}, {"t": "9.42 Assistant assumes memory that new customers don't have", "u": "memory.html#mem-18", "s": "Memory & Context", "k": "Quality FinTech An empty memory must be said out loud "}, {"t": "9.43 Memory feature launched with no memory evals", "u": "memory.html#mem-19", "s": "Memory & Context", "k": "Quality Compliance Telco If memory isn t evaluated  it s accumulating errors "}, {"t": "9.44 Branch kiosk shows the previous customer's context", "u": "memory.html#mem-20", "s": "Memory & Context", "k": "Quality FinTech Critical On shared devices  every new question might be a new person "}, {"t": "10. Tool Design, MCP & A2A", "u": "protocols.html", "s": "Section"}, {"t": "10.1 Custom tool integrations per agent instead of a shared protocol", "u": "protocols.html#bespoke-integrations", "s": "Tools, MCP & A2A", "k": "Cost Scale Integrate each system once as an MCP server  govern access at a gateway  and let every agent reuse it "}, {"t": "10.2 MCP servers and A2A endpoints without authentication or trust boundaries", "u": "protocols.html#unauthenticated-mcp", "s": "Tools, MCP & A2A", "k": "Security MCP and A2A make integration easy  including for attackers  Allow list  pin  authenticate  sandbox  and treat tool metadata as untrusted input "}, {"t": "10.3 Over-privileged service accounts for agents", "u": "protocols.html#overprivileged-agents", "s": "Tools, MCP & A2A", "k": "Security Compliance An agent should never be more powerful than the person it serves  Give agents their own identity  delegate with OBO  and keep scopes narrow and short lived "}, {"t": "10.4 Provider-specific tool code in every app", "u": "protocols.html#provider-specific-tool-code", "s": "Tools, MCP & A2A", "k": "Cost Scale Build a tool once  as an MCP server with its own owner  auth and audit  Don t rewrite it inside every app "}, {"t": "10.5 Agent given a raw SQL tool on the billing database", "u": "protocols.html#tool-01", "s": "Tools, MCP & A2A", "k": "Reliability Latency Security Telco Critical Give agents verbs for the business  not a shell into the database "}, {"t": "10.6 Wire value date in the wrong time zone", "u": "protocols.html#tool-02", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Never let the model guess what tomorrow means "}, {"t": "10.7 get_bill, get_invoice and get_statement all exist", "u": "protocols.html#tool-03", "s": "Tools, MCP & A2A", "k": "Reliability Telco One task  one tool  Hide the plumbing "}, {"t": "10.8 Transaction tool returns 10,000 rows", "u": "protocols.html#tool-04", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Every list tool needs filters  pages and totals "}, {"t": "10.9 Plan change executed without a preview", "u": "protocols.html#tool-05", "s": "Tools, MCP & A2A", "k": "Reliability Telco Preview before you commit "}, {"t": "10.10 Bulk suspension reports success when 3 of 50 lines failed", "u": "protocols.html#tool-06", "s": "Tools, MCP & A2A", "k": "Reliability Cost Telco Bulk tools must report per item truth "}, {"t": "10.11 Statement tool trusts the account id the model supplies", "u": "protocols.html#tool-07", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Critical Identity comes from the session  never from the prompt "}, {"t": "10.12 Legacy OSS call with no timeout hangs the conversation", "u": "protocols.html#tool-08", "s": "Tools, MCP & A2A", "k": "Reliability Latency Telco Every tool call needs a deadline "}, {"t": "10.13 Tool schema changed in place breaks deployed agents", "u": "protocols.html#tool-09", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Tools are APIs  Version them like APIs "}, {"t": "10.14 MCP server exposes the whole BSS API with an admin token", "u": "protocols.html#tool-10", "s": "Tools, MCP & A2A", "k": "Reliability Security Telco Critical MCP standardises access  You still have to scope it "}, {"t": "10.15 Tool description promises something the tool doesn't do", "u": "protocols.html#tool-11", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Tool docs are a contract with the model  Test them "}, {"t": "10.16 Port-in tool blocks for hours waiting for completion", "u": "protocols.html#tool-12", "s": "Tools, MCP & A2A", "k": "Reliability Telco Long processes return a ticket  not a result "}, {"t": "10.17 Agent hammers the mainframe core-banking system", "u": "protocols.html#tool-13", "s": "Tools, MCP & A2A", "k": "Reliability Cost Latency FinTech Protect legacy systems from enthusiastic agents "}, {"t": "10.18 Agent trusts a coverage tool's malformed response", "u": "protocols.html#tool-14", "s": "Tools, MCP & A2A", "k": "Reliability Telco Missing data means unknown  never yes "}, {"t": "10.19 Balance unchanged right after the payment, so the agent pays again", "u": "protocols.html#tool-15", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Confirm a write with its receipt  not with a read "}, {"t": "10.20 A generic http_request tool for everything", "u": "protocols.html#tool-16", "s": "Tools, MCP & A2A", "k": "Reliability Security Telco Generic tools are generic attack surface "}, {"t": "10.21 Tool returns ACH return code R03 with no explanation", "u": "protocols.html#tool-17", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Return meaning and next step  not just codes "}, {"t": "10.22 Tool returns a formatted paragraph the agent must parse", "u": "protocols.html#tool-18", "s": "Tools, MCP & A2A", "k": "Reliability Telco Tools should return data  Let the agent write the prose "}, {"t": "10.23 Two MCP servers both offer a tool named transfer", "u": "protocols.html#tool-19", "s": "Tools, MCP & A2A", "k": "Reliability FinTech Tool names need namespaces once you have more than one server "}, {"t": "10.24 No one knows which tools agents actually use", "u": "protocols.html#tool-20", "s": "Tools, MCP & A2A", "k": "Reliability Telco You can t retire what you can t see being used "}, {"t": "11. LLM & Agent Evaluation", "u": "evals-ops.html", "s": "Section"}, {"t": "11.1 Shipping on \"vibe checks\" with no evaluation suite", "u": "evals-ops.html#vibe-checks", "s": "LLM & Agent Evaluation", "k": "Quality Reliability No eval suite  no production  The golden dataset and thresholds are how you turn a demo into a decision "}, {"t": "11.2 Only end-to-end evaluation, nothing per component", "u": "evals-ops.html#e2e-only-evals", "s": "LLM & Agent Evaluation", "k": "Quality Evaluate the pipeline the way you d test software  unit metrics per stage  integration metrics end to end "}, {"t": "11.3 No tracing of agent trajectories", "u": "evals-ops.html#no-agent-tracing", "s": "LLM & Agent Evaluation", "k": "Reliability Compliance If you can t replay an agent s trajectory  you can t debug it  defend it or optimize it  Trace every step with OpenTelemetry "}, {"t": "11.4 LLM-as-judge without calibration", "u": "evals-ops.html#uncalibrated-judge", "s": "LLM & Agent Evaluation", "k": "Quality An LLM judge is a classifier  Give it a binary rubric  measure its agreement with experts  and re calibrate it before trusting its numbers "}, {"t": "11.5 No regression gating in CI/CD", "u": "evals-ops.html#no-regression-gate", "s": "LLM & Agent Evaluation", "k": "Reliability Quality Every prompt  model and retrieval change is a release  Gate it with evals in CI  canary it  and plan model deprecations ahead "}, {"t": "11.6 A golden set of 50 questions from one team", "u": "evals-ops.html#golden-set-one-team", "s": "LLM & Agent Evaluation", "k": "Quality Scale A golden set from one team measures one team s questions  Stratify by real traffic  keep special slices  and gate on every slice "}, {"t": "11.7 Bill-explanation prompt shipped after a vibe check", "u": "evals-ops.html#eval-01", "s": "LLM & Agent Evaluation", "k": "Quality Telco If it isn t in the eval set  it isn t protected "}, {"t": "11.8 ROUGE scores a collections-call summary that drops the dispute", "u": "evals-ops.html#eval-02", "s": "LLM & Agent Evaluation", "k": "Quality Compliance FinTech Critical Measure what customers and regulators care about  not word overlap "}, {"t": "11.9 LLM judge loves retention chats humans rate poorly", "u": "evals-ops.html#eval-03", "s": "LLM & Agent Evaluation", "k": "Quality Telco A judge is a model too  so evaluate the evaluator "}, {"t": "11.10 Complaint classifier judged on a 1-10 scale", "u": "evals-ops.html#eval-04", "s": "LLM & Agent Evaluation", "k": "Quality Compliance FinTech Binary criteria beat fuzzy scales "}, {"t": "11.11 Eval set frozen before the eSIM-only phone launch", "u": "evals-ops.html#eval-05", "s": "LLM & Agent Evaluation", "k": "Quality Telco Every production bug becomes a test case "}, {"t": "11.12 Investment-app assistant tested only on friendly questions", "u": "evals-ops.html#eval-06", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Test the inputs you didn t design for "}, {"t": "11.13 Prompt A/B declared a winner on 100 examples", "u": "evals-ops.html#eval-07", "s": "LLM & Agent Evaluation", "k": "Quality Telco A 2  gain on 100 examples is noise "}, {"t": "11.14 KYC extraction few-shots leaked into the eval set", "u": "evals-ops.html#eval-08", "s": "LLM & Agent Evaluation", "k": "Quality Security Compliance FinTech Never grade on the answer key you handed out "}, {"t": "11.15 92% overall hides 55% on business billing disputes", "u": "evals-ops.html#eval-09", "s": "LLM & Agent Evaluation", "k": "Quality Telco Report the worst slice  not just the mean "}, {"t": "11.16 No safety suite before the investing assistant launch", "u": "evals-ops.html#eval-10", "s": "LLM & Agent Evaluation", "k": "Quality Cost Security FinTech Critical Safety is a separate test suite with zero tolerance "}, {"t": "11.17 Offline gains that never move first-contact resolution", "u": "evals-ops.html#eval-11", "s": "LLM & Agent Evaluation", "k": "Quality Telco Offline evals are a proxy  so validate the proxy "}, {"t": "11.18 Same model grades its own dispute letters", "u": "evals-ops.html#eval-12", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Don t let the student grade their own exam "}, {"t": "11.19 Order-capture pipeline regresses and nobody knows which step", "u": "evals-ops.html#eval-13", "s": "LLM & Agent Evaluation", "k": "Quality Cost Telco Unit tests and integration tests apply to LLM systems too "}, {"t": "11.20 Best fraud-summary prompt is too slow and too costly", "u": "evals-ops.html#eval-14", "s": "LLM & Agent Evaluation", "k": "Quality Cost Latency FinTech Quality  latency and cost are one decision "}, {"t": "11.21 Prompt tweak breaks the B2B quote JSON for a key account", "u": "evals-ops.html#eval-15", "s": "LLM & Agent Evaluation", "k": "Quality Telco Evals belong in CI  like unit tests "}, {"t": "11.22 Engineers label SAR narrative quality", "u": "evals-ops.html#eval-16", "s": "LLM & Agent Evaluation", "k": "Quality Compliance FinTech Your eval is only as good as your labels "}, {"t": "11.23 Fifty prompt iterations overfit the eval set", "u": "evals-ops.html#eval-17", "s": "LLM & Agent Evaluation", "k": "Quality Telco Hold out a set you never tune on "}, {"t": "11.24 Payment instructions from emails fail to parse 3% of the time", "u": "evals-ops.html#eval-18", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Check format with code  not with a judge "}, {"t": "11.25 Unpinned model alias changes refusal behaviour overnight", "u": "evals-ops.html#eval-19", "s": "LLM & Agent Evaluation", "k": "Quality Telco The model is a dependency  so pin it and test upgrades "}, {"t": "11.26 Eval dashboard with no owner and no threshold", "u": "evals-ops.html#eval-20", "s": "LLM & Agent Evaluation", "k": "Quality Latency FinTech Every metric needs a threshold and an owner "}, {"t": "11.27 eSIM agent says activated, but no profile was installed", "u": "evals-ops.html#aev-01", "s": "LLM & Agent Evaluation", "k": "Quality Telco Check the world  not the agent s claim about the world "}, {"t": "11.28 Dispute agent grants provisional credit before verifying identity", "u": "evals-ops.html#aev-02", "s": "LLM & Agent Evaluation", "k": "Quality FinTech How the agent got there matters as much as where it landed "}, {"t": "11.29 Plan-change evals demand one exact tool sequence", "u": "evals-ops.html#aev-03", "s": "LLM & Agent Evaluation", "k": "Quality Telco Grade constraints  not a script "}, {"t": "11.30 Collections agent eval sends real emails to customers", "u": "evals-ops.html#aev-04", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Critical Agent evals need a simulator  not production "}, {"t": "11.31 Clean mocks hide real BSS behaviour", "u": "evals-ops.html#aev-05", "s": "LLM & Agent Evaluation", "k": "Quality Security Telco Test the agent on a bad day "}, {"t": "11.32 KYC remediation agent passes once, fails three runs in ten", "u": "evals-ops.html#aev-06", "s": "LLM & Agent Evaluation", "k": "Quality Compliance FinTech Users need pass k  not pass k "}, {"t": "11.33 Plan-change agent tested with complete one-line requests", "u": "evals-ops.html#aev-07", "s": "LLM & Agent Evaluation", "k": "Quality Telco Simulate the user  not just the request "}, {"t": "11.34 New agent version is 3% better and 4 times the cost", "u": "evals-ops.html#aev-08", "s": "LLM & Agent Evaluation", "k": "Quality Cost FinTech Efficiency is part of correctness for agents "}, {"t": "11.35 Retention agent waives the termination fee under pressure", "u": "evals-ops.html#aev-09", "s": "LLM & Agent Evaluation", "k": "Quality Compliance Telco Test whether the agent says no when it should "}, {"t": "11.36 20% failure rate with no idea which decision failed", "u": "evals-ops.html#aev-10", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Decompose agent failures into decision types "}, {"t": "11.37 Port-in agent gives up on the first rejection", "u": "evals-ops.html#aev-11", "s": "LLM & Agent Evaluation", "k": "Quality Telco Score recovery  not just success "}, {"t": "11.38 Agent says the card is frozen but never called the tool", "u": "evals-ops.html#aev-12", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Critical Every claimed action must appear in the trace "}, {"t": "11.39 Framework chosen on a public benchmark fails on BSS workflows", "u": "evals-ops.html#aev-13", "s": "LLM & Agent Evaluation", "k": "Quality Telco Your tasks are the only benchmark that matters "}, {"t": "11.40 Agent eval scores swing with live FX rates", "u": "evals-ops.html#aev-14", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Reproducible environments make agent evals comparable "}, {"t": "11.41 B2B move agent fine at 3 steps, lost at 30", "u": "evals-ops.html#aev-15", "s": "LLM & Agent Evaluation", "k": "Quality Telco Reliability decays with horizon  so measure the curve "}, {"t": "11.42 Accounts-payable agent changes a vendor's bank details from an email", "u": "evals-ops.html#aev-16", "s": "LLM & Agent Evaluation", "k": "Quality Security FinTech Critical For agents  safety is measured in actions "}, {"t": "11.43 Automated scores look fine, but nobody reads the traces", "u": "evals-ops.html#aev-17", "s": "LLM & Agent Evaluation", "k": "Quality Telco Read the traces  Then automate what you find "}, {"t": "11.44 Planner prompt change silently breaks the payment executor", "u": "evals-ops.html#aev-18", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Test agents alone and together "}, {"t": "11.45 Judge approves an answer that contradicts the tool result", "u": "evals-ops.html#aev-19", "s": "LLM & Agent Evaluation", "k": "Quality Telco A judge needs the evidence to judge grounding "}, {"t": "11.46 Offline evals pass while customers redo tasks by hand", "u": "evals-ops.html#aev-20", "s": "LLM & Agent Evaluation", "k": "Quality FinTech Human takeover rate is the truest agent metric "}, {"t": "12. Guardrails, AI Security & Responsible AI", "u": "security-gov.html", "s": "Section"}, {"t": "12.1 No defense against direct and indirect prompt injection", "u": "security-gov.html#prompt-injection", "s": "Guardrails & AI Security", "k": "Security Prompt injection is an architecture problem  Never combine private data  untrusted content and an exfiltration channel in one agent context without a break "}, {"t": "12.2 No human in the loop for high-impact actions", "u": "security-gov.html#no-hitl", "s": "Guardrails & AI Security", "k": "Compliance Security Autonomy should be proportional to impact  Tier decisions by risk  and give reviewers evidence  not a button "}, {"t": "12.3 No centralized guardrails layer", "u": "security-gov.html#no-guardrail-layer", "s": "Guardrails & AI Security", "k": "Security Compliance Scale Safety shouldn t depend on which team built the app  Centralize baseline guardrails in a gateway  as policy as code owned by risk "}, {"t": "12.4 No model risk management or audit trail", "u": "security-gov.html#no-model-risk-mgmt", "s": "Guardrails & AI Security", "k": "Compliance Governance that slows delivery gets bypassed  Make it a lightweight  tiered lifecycle fed by automated evidence "}, {"t": "12.5 No cost governance (AI FinOps)", "u": "security-gov.html#no-finops", "s": "Guardrails & AI Security", "k": "Cost Every AI call should be attributable to a use case and a business outcome  Cost per resolved ticket is the metric that decides where to scale "}, {"t": "12.6 Bank bot role-played into explaining deposit structuring", "u": "security-gov.html#sec-01", "s": "Guardrails & AI Security", "k": "Security FinTech Critical Framing changes the request  not the risk  Check the output "}, {"t": "12.7 Field-tech agent obeys hidden text on a vendor web page", "u": "security-gov.html#sec-02", "s": "Guardrails & AI Security", "k": "Security Telco Every web page is untrusted input "}, {"t": "12.8 Retention offer tiers extracted from the system prompt", "u": "security-gov.html#sec-03", "s": "Guardrails & AI Security", "k": "Security Telco If it s in the prompt  assume it s public "}, {"t": "12.9 Store copilot shows another subscriber's call records", "u": "security-gov.html#sec-04", "s": "Guardrails & AI Security", "k": "Security Telco Critical Authorise every object  every call "}, {"t": "12.10 Banking agent can pay new payees on its own", "u": "security-gov.html#sec-05", "s": "Guardrails & AI Security", "k": "Security Compliance FinTech Critical The agent can request money movement  It can t approve it "}, {"t": "12.11 EU subscriber data sent to a model in another region", "u": "security-gov.html#sec-06", "s": "Guardrails & AI Security", "k": "Security Compliance Telco The model boundary is a data transfer boundary "}, {"t": "12.12 Model output rendered as HTML in the agent desktop", "u": "security-gov.html#sec-07", "s": "Guardrails & AI Security", "k": "Security FinTech Model output is user input with extra steps "}, {"t": "12.13 Bot promises 5G coverage at an address it can't check", "u": "security-gov.html#sec-08", "s": "Guardrails & AI Security", "k": "Security Compliance Telco Claims need evidence from a tool  not from vibes "}, {"t": "12.14 Guardrails on input only", "u": "security-gov.html#sec-09", "s": "Guardrails & AI Security", "k": "Security FinTech Defence in depth  Every layer will fail sometimes "}, {"t": "12.15 The LLM is asked whether the caller is authorised", "u": "security-gov.html#sec-10", "s": "Guardrails & AI Security", "k": "Security Telco Critical Never let the model decide who someone is "}, {"t": "12.16 Content filter bypassed with base64 and another language", "u": "security-gov.html#sec-11", "s": "Guardrails & AI Security", "k": "Security Telco Filters slow attackers down  Authorisation stops them "}, {"t": "12.17 Cloned voice passes voice biometrics on the IVR agent", "u": "security-gov.html#sec-12", "s": "Guardrails & AI Security", "k": "Security Telco Critical Voice is a signal  not a key "}, {"t": "12.18 Coordinated thumbs-up teaches the bot to waive fees", "u": "security-gov.html#sec-13", "s": "Guardrails & AI Security", "k": "Security FinTech Feedback is a signal  not a label "}, {"t": "12.19 Community MCP server installed in the NOC agent", "u": "security-gov.html#sec-14", "s": "Guardrails & AI Security", "k": "Security Telco A tool is code plus a prompt  Vet both "}, {"t": "12.20 Huge pasted inputs exhaust the assistant's capacity", "u": "security-gov.html#sec-15", "s": "Guardrails & AI Security", "k": "Security Cost Latency FinTech Every input is a cost the user chooses for you "}, {"t": "12.21 Deleted customer still found in the vector store", "u": "security-gov.html#sec-16", "s": "Guardrails & AI Security", "k": "Security Telco Derived data is still personal data "}, {"t": "12.22 Analytics agent's code runs with network access", "u": "security-gov.html#sec-17", "s": "Guardrails & AI Security", "k": "Security FinTech Critical Generated code is untrusted code  Sandbox it "}, {"t": "12.23 Agent installs a hallucinated package name", "u": "security-gov.html#sec-18", "s": "Guardrails & AI Security", "k": "Security Telco An agent s dependencies are your supply chain "}, {"t": "12.24 Approvers rubber-stamp the agent's persuasive summaries", "u": "security-gov.html#sec-19", "s": "Guardrails & AI Security", "k": "Security FinTech Humans in the loop need evidence  not just a summary "}, {"t": "12.25 An AI security incident with no playbook", "u": "security-gov.html#sec-20", "s": "Guardrails & AI Security", "k": "Security Telco If the SOC can t see it  it can t defend it "}, {"t": "13. Observability & Telemetry", "u": "observability.html", "s": "Section"}, {"t": "13.1 All dashboards green while the bot invents outage ETAs", "u": "observability.html#obs-01", "s": "Observability & Telemetry", "k": "Reliability Latency Telco In LLM systems  200 OK doesn t mean correct "}, {"t": "13.2 Wrong escrow answer cannot be reconstructed", "u": "observability.html#obs-02", "s": "Observability & Telemetry", "k": "Reliability FinTech Every answer should be replayable from its trace "}, {"t": "13.3 Two thousand thumbs-down clicks with no trace", "u": "observability.html#obs-03", "s": "Observability & Telemetry", "k": "Reliability Telco Feedback is only useful when it points to a trace "}, {"t": "13.4 Average latency hides 40-second dispute answers", "u": "observability.html#obs-04", "s": "Observability & Telemetry", "k": "Reliability Latency FinTech Users experience the tail  not the mean "}, {"t": "13.5 One MVNO tenant burns the monthly LLM budget in a week", "u": "observability.html#obs-05", "s": "Observability & Telemetry", "k": "Reliability Cost Telco Tokens are money  so meter them like money "}, {"t": "13.6 Tax-season questions drift outside what the bot knows", "u": "observability.html#obs-06", "s": "Observability & Telemetry", "k": "Reliability FinTech Watch the inputs  not just the outputs "}, {"t": "13.7 Nobody can explain why the agent cancelled a line", "u": "observability.html#obs-07", "s": "Observability & Telemetry", "k": "Reliability Compliance Telco For agents  the audit trail is a product requirement "}, {"t": "13.8 Forty dashboards and no SLO during an incident", "u": "observability.html#obs-08", "s": "Observability & Telemetry", "k": "Reliability Cost FinTech Define SLOs first  dashboards second "}, {"t": "13.9 Team rewrites prompts while an index shard is empty", "u": "observability.html#obs-09", "s": "Observability & Telemetry", "k": "Reliability Telco Observe retrieval as closely as generation "}, {"t": "13.10 PII filter blocks 15% of legitimate account questions", "u": "observability.html#obs-10", "s": "Observability & Telemetry", "k": "Reliability Security FinTech Monitor your guardrails like any other model "}, {"t": "13.11 Quality dip that can't be split by prompt version", "u": "observability.html#obs-11", "s": "Observability & Telemetry", "k": "Reliability Telco Version tags turn a mystery into a diff "}, {"t": "13.12 Payday 429s blamed on application bugs", "u": "observability.html#obs-12", "s": "Observability & Telemetry", "k": "Reliability Cost FinTech Your provider is a dependency  so observe it "}, {"t": "13.13 Every reply looks fine but customers abandon long chats", "u": "observability.html#obs-13", "s": "Observability & Telemetry", "k": "Reliability Telco Customers judge conversations  not single replies "}, {"t": "13.14 Silent fallback to a weaker model for three days", "u": "observability.html#obs-14", "s": "Observability & Telemetry", "k": "Reliability Latency FinTech Every fallback should leave a footprint "}, {"t": "13.15 Diagnosis agent repeats the same check 200 times overnight", "u": "observability.html#obs-15", "s": "Observability & Telemetry", "k": "Reliability Cost Telco Detect loops in minutes  not on the invoice "}, {"t": "13.16 Traces redacted so heavily that nothing can be debugged", "u": "observability.html#obs-16", "s": "Observability & Telemetry", "k": "Reliability FinTech Redact precisely  not bluntly "}, {"t": "13.17 Every failure logged as \"LLM error\"", "u": "observability.html#obs-17", "s": "Observability & Telemetry", "k": "Reliability Latency Telco Name your failure modes  then count them "}, {"t": "13.18 Online judge on 100% of traffic costs more than the product", "u": "observability.html#obs-18", "s": "Observability & Telemetry", "k": "Reliability Cost Latency FinTech Sample smart  judge asynchronously "}, {"t": "13.19 Bot promises outage credits and nobody knows how to stop it", "u": "observability.html#obs-19", "s": "Observability & Telemetry", "k": "Reliability Telco Plan the rollback before you need it "}, {"t": "13.20 First-week incident with no data to debug", "u": "observability.html#obs-20", "s": "Observability & Telemetry", "k": "Reliability Cost FinTech Instrument before you launch  not after the first incident "}, {"t": "13.21 Switching trace vendors means rewriting 30 services", "u": "observability.html#tel-01", "s": "Observability & Telemetry", "k": "Reliability Cost FinTech Instrument once with OpenTelemetry  export anywhere "}, {"t": "13.22 Customer addresses and call records found in the logging platform", "u": "observability.html#tel-02", "s": "Observability & Telemetry", "k": "Reliability Security Compliance Telco Critical Prompts are customer data  so treat logs as a data store "}, {"t": "13.23 Account ID as a metric label explodes the metrics bill", "u": "observability.html#tel-03", "s": "Observability & Telemetry", "k": "Reliability Cost Latency FinTech Metrics for aggregates  traces for individuals "}, {"t": "13.24 Three teams report token usage three different ways", "u": "observability.html#tel-04", "s": "Observability & Telemetry", "k": "Reliability Cost Telco Standardise the schema before you build the dashboard "}, {"t": "13.25 The 1% trace sample contains almost no failed disputes", "u": "observability.html#tel-05", "s": "Observability & Telemetry", "k": "Reliability Cost FinTech Sample after you know whether the request was interesting "}, {"t": "13.26 Slow tracing backend slows down customer replies", "u": "observability.html#tel-06", "s": "Observability & Telemetry", "k": "Reliability Latency Telco Telemetry must never take down the thing it watches "}, {"t": "13.27 Traces stop at the Kafka topic between fraud scoring and the agent", "u": "observability.html#tel-07", "s": "Observability & Telemetry", "k": "Reliability FinTech A trace is only as complete as its weakest hop "}, {"t": "13.28 Voice bot feels slow, but total latency looks fine", "u": "observability.html#tel-08", "s": "Observability & Telemetry", "k": "Reliability Latency Telco For streaming  time to first token is the UX metric "}, {"t": "13.29 GDPR deletion request no one can fulfil in the trace store", "u": "observability.html#tel-09", "s": "Observability & Telemetry", "k": "Reliability Compliance FinTech Retention is a design decision  not a default "}, {"t": "13.30 Which prompt produced last Tuesday's bad answer?", "u": "observability.html#tel-10", "s": "Observability & Telemetry", "k": "Reliability Telco Stamp every span with what was deployed "}, {"t": "13.31 A 12-second gap in the trace is an uninstrumented bureau call", "u": "observability.html#tel-11", "s": "Observability & Telemetry", "k": "Reliability Latency FinTech No gaps in the trace "}, {"t": "13.32 Cost estimates 15% off the provider bill", "u": "observability.html#tel-12", "s": "Observability & Telemetry", "k": "Reliability Cost Telco Use the provider s usage numbers as the source of truth "}, {"t": "13.33 Support tickets are the only quality signal", "u": "observability.html#tel-13", "s": "Observability & Telemetry", "k": "Reliability FinTech Implicit feedback is free telemetry "}, {"t": "13.34 Finding failed refunds means regex over 500 GB of logs", "u": "observability.html#tel-14", "s": "Observability & Telemetry", "k": "Reliability Cost Telco Log events  not sentences "}, {"t": "13.35 BaaS partner sees another partner's prompts in shared dashboards", "u": "observability.html#tel-15", "s": "Observability & Telemetry", "k": "Reliability FinTech Critical Telemetry inherits the data s security requirements "}, {"t": "13.36 Eval results live only in CI logs", "u": "observability.html#tel-16", "s": "Observability & Telemetry", "k": "Reliability Latency Telco Eval results are telemetry too "}, {"t": "13.37 Child spans appear to start before their parents", "u": "observability.html#tel-17", "s": "Observability & Telemetry", "k": "Reliability Latency FinTech Durations from monotonic clocks  timestamps from synced clocks "}, {"t": "13.38 Telemetry is 40% of infrastructure cost", "u": "observability.html#tel-18", "s": "Observability & Telemetry", "k": "Reliability Cost Compliance Telco Telemetry has a cost to value ratio  Manage it "}, {"t": "13.39 Logs show the template, not the prompt the model saw", "u": "observability.html#tel-19", "s": "Observability & Telemetry", "k": "Reliability FinTech Log what the model saw  not what you meant to send "}, {"t": "13.40 Bill explanations cut off mid-sentence for large accounts", "u": "observability.html#tel-20", "s": "Observability & Telemetry", "k": "Reliability Telco The stop reason is the first thing to check "}, {"t": "14. LLMOps & CI/CD for Agentic AI", "u": "llmops-cicd.html", "s": "Section"}, {"t": "14.1 Last week's bad answer can't be reproduced", "u": "llmops-cicd.html#ops-01", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Reproducibility needs the whole bundle versioned "}, {"t": "14.2 Intent model trained on clean text, served on raw transcripts", "u": "llmops-cicd.html#ops-02", "s": "LLMOps & CI/CD", "k": "Reliability Telco Same transform in training and serving "}, {"t": "14.3 Fine-tuning a model on monthly price plans", "u": "llmops-cicd.html#ops-03", "s": "LLMOps & CI/CD", "k": "Reliability Cost Latency Telco RAG for knowledge  fine tuning for behaviour "}, {"t": "14.4 Collections model fine-tuned on raw call transcripts", "u": "llmops-cicd.html#ops-04", "s": "LLMOps & CI/CD", "k": "Reliability Compliance FinTech Fine tuning amplifies your data  good and bad "}, {"t": "14.5 Nobody knows which data trained the credit-memo model", "u": "llmops-cicd.html#ops-05", "s": "LLMOps & CI/CD", "k": "Reliability Cost Compliance FinTech Every production model should have a birth certificate "}, {"t": "14.6 All traffic switched to a new model at once", "u": "llmops-cicd.html#ops-06", "s": "LLMOps & CI/CD", "k": "Reliability Telco Shadow  canary  then ramp "}, {"t": "14.7 Twelve teams call four providers directly", "u": "llmops-cicd.html#ops-07", "s": "LLMOps & CI/CD", "k": "Reliability Cost Security FinTech Centralise model access the way you centralise database access "}, {"t": "14.8 Self-hosted model runs out of GPU memory at 50 users", "u": "llmops-cicd.html#ops-08", "s": "LLMOps & CI/CD", "k": "Reliability Cost Telco Plan GPU capacity for concurrency times context length "}, {"t": "14.9 Cost per call falls while cost per resolved dispute triples", "u": "llmops-cicd.html#ops-09", "s": "LLMOps & CI/CD", "k": "Reliability Cost FinTech Optimise cost per success  not cost per call "}, {"t": "14.10 Thirty percent of questions are the same and all pay full price", "u": "llmops-cicd.html#ops-10", "s": "LLMOps & CI/CD", "k": "Reliability Telco The cheapest token is the one you never generate "}, {"t": "14.11 Notebook works, the production rewrite doesn't", "u": "llmops-cicd.html#ops-11", "s": "LLMOps & CI/CD", "k": "Reliability Compliance FinTech Promote artifacts  not notebooks "}, {"t": "14.12 A year of care-bot feedback never used", "u": "llmops-cicd.html#ops-12", "s": "LLMOps & CI/CD", "k": "Reliability Telco Close the loop from feedback to the next release "}, {"t": "14.13 Minor framework update changes default chunk size", "u": "llmops-cicd.html#ops-13", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Pin fast moving libraries and upgrade on purpose "}, {"t": "14.14 Staging uses a small model and a tiny index", "u": "llmops-cicd.html#ops-14", "s": "LLMOps & CI/CD", "k": "Reliability Latency Telco Staging should be cheaper  not different "}, {"t": "14.15 Compliance asks which systems use AI for credit decisions", "u": "llmops-cicd.html#ops-15", "s": "LLMOps & CI/CD", "k": "Reliability Compliance FinTech You can t govern what you haven t inventoried "}, {"t": "14.16 Model deprecation forces an emergency migration", "u": "llmops-cicd.html#ops-16", "s": "LLMOps & CI/CD", "k": "Reliability Telco Always have a tested second model "}, {"t": "14.17 Tax-day traffic hits provider quotas", "u": "llmops-cicd.html#ops-17", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Provider quotas are part of capacity planning "}, {"t": "14.18 Re-embedding 50 million chunks by hand", "u": "llmops-cicd.html#ops-18", "s": "LLMOps & CI/CD", "k": "Reliability Telco Index builds should be a pipeline  not a project "}, {"t": "14.19 API key in a public notebook runs up the bill", "u": "llmops-cicd.html#ops-19", "s": "LLMOps & CI/CD", "k": "Reliability Cost FinTech LLM keys are credit cards  Protect them like credit cards "}, {"t": "14.20 Forty old prompts, nine indexes and three fine-tunes still billed", "u": "llmops-cicd.html#ops-20", "s": "LLMOps & CI/CD", "k": "Reliability Cost Compliance Telco Retire what you don t run "}, {"t": "14.21 Pipeline runs unit tests but no evals", "u": "llmops-cicd.html#cicd-01", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Evals are a pipeline stage  not a notebook "}, {"t": "14.22 Prompts edited live in a vendor console", "u": "llmops-cicd.html#cicd-02", "s": "LLMOps & CI/CD", "k": "Reliability Telco If it changes behaviour  it goes through the pipeline "}, {"t": "14.23 Tool wrappers and templates have no unit tests", "u": "llmops-cicd.html#cicd-03", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Most of an agent is ordinary code  Test it like ordinary code "}, {"t": "14.24 Two-hour eval suite on every PR gets skipped", "u": "llmops-cicd.html#cicd-04", "s": "LLMOps & CI/CD", "k": "Reliability Cost Telco Fast evals get run  Slow evals get skipped "}, {"t": "14.25 New prompt goes to all customers at once", "u": "llmops-cicd.html#cicd-05", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Every change gets a canary "}, {"t": "14.26 Model version bumped as a one-line config change", "u": "llmops-cicd.html#cicd-06", "s": "LLMOps & CI/CD", "k": "Reliability Telco The model is a dependency  Upgrades are releases "}, {"t": "14.27 Same commit builds two different agents", "u": "llmops-cicd.html#cicd-07", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Build once  promote the same artifact "}, {"t": "14.28 CI agent evals call the production BSS", "u": "llmops-cicd.html#cicd-08", "s": "LLMOps & CI/CD", "k": "Reliability Security Telco Critical CI should never be able to touch production "}, {"t": "14.29 Rollback restores the code but not the index", "u": "llmops-cicd.html#cicd-09", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Roll back the whole bundle  not just the code "}, {"t": "14.30 Flaky evals fixed with retry until green", "u": "llmops-cicd.html#cicd-10", "s": "LLMOps & CI/CD", "k": "Reliability Telco Don t retry until green  Measure the distribution "}, {"t": "14.31 Knowledge articles published straight into the live index", "u": "llmops-cicd.html#cicd-11", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Content is code for a RAG system "}, {"t": "14.32 Planner and executor agents never tested together", "u": "llmops-cicd.html#cicd-12", "s": "LLMOps & CI/CD", "k": "Reliability Telco Test agents alone and together "}, {"t": "14.33 No red-team stage in the release pipeline", "u": "llmops-cicd.html#cicd-13", "s": "LLMOps & CI/CD", "k": "Reliability Security FinTech Every release gets attacked before customers attack it "}, {"t": "14.34 Provider API key printed in CI logs", "u": "llmops-cicd.html#cicd-14", "s": "LLMOps & CI/CD", "k": "Reliability Telco CI logs are public inside the company "}, {"t": "14.35 Regulated disclosure change shipped without sign-off", "u": "llmops-cicd.html#cicd-15", "s": "LLMOps & CI/CD", "k": "Reliability Compliance FinTech Regulated changes need a named approver in the pipeline "}, {"t": "14.36 No way to switch off one agent capability", "u": "llmops-cicd.html#cicd-16", "s": "LLMOps & CI/CD", "k": "Reliability Telco Ship capabilities behind switches "}, {"t": "14.37 Eval set changed and scores aren't comparable", "u": "llmops-cicd.html#cicd-17", "s": "LLMOps & CI/CD", "k": "Reliability FinTech Version the test set like the code "}, {"t": "14.38 BSS API change breaks the agent's tools in production", "u": "llmops-cicd.html#cicd-18", "s": "LLMOps & CI/CD", "k": "Reliability Cost Telco Tools are integrations  Test the contract "}, {"t": "14.39 Cost regression merged without anyone noticing", "u": "llmops-cicd.html#cicd-19", "s": "LLMOps & CI/CD", "k": "Reliability Cost FinTech Cost is a test result too "}, {"t": "14.40 Deployment succeeds but the bot can't reach the catalog", "u": "llmops-cicd.html#cicd-20", "s": "LLMOps & CI/CD", "k": "Reliability Telco Deployed isn t done  Verify the journeys "}, {"t": "15. Human-in-the-Loop & AI Governance", "u": "governance.html", "s": "Section"}, {"t": "15.1 LLM credit-memo tool deployed outside model risk management", "u": "governance.html#gov-01", "s": "Human Oversight & Governance", "k": "Compliance FinTech If it influences a decision  it s a model  Govern it like one "}, {"t": "15.2 Disconnect and port-out executed with no human gate", "u": "governance.html#gov-02", "s": "Human Oversight & Governance", "k": "Compliance Telco Critical The less reversible the action  the more human the decision "}, {"t": "15.3 Customers aren't told they're talking to an AI", "u": "governance.html#gov-03", "s": "Human Oversight & Governance", "k": "Compliance FinTech Tell people when they re talking to a machine "}, {"t": "15.4 Customers trapped in a chatbot doom loop", "u": "governance.html#gov-04", "s": "Human Oversight & Governance", "k": "Compliance FinTech Never trap a customer with a bot "}, {"t": "15.5 LLM-assisted credit decline can't give specific reasons", "u": "governance.html#gov-05", "s": "Human Oversight & Governance", "k": "Compliance FinTech Critical The LLM can write the letter  It can t be the decision "}, {"t": "15.6 Retention offers differ by customer name and dialect", "u": "governance.html#gov-06", "s": "Human Oversight & Governance", "k": "Compliance Telco Same facts  same outcome  whatever the name or accent "}, {"t": "15.7 Broker's AI client chats aren't archived", "u": "governance.html#gov-07", "s": "Human Oversight & Governance", "k": "Compliance FinTech An AI conversation with a client is a client communication "}, {"t": "15.8 AI incident with no clear owner", "u": "governance.html#gov-08", "s": "Human Oversight & Governance", "k": "Compliance Telco Every AI use case needs one accountable owner "}, {"t": "15.9 Call records used to fine-tune a model without a legal basis", "u": "governance.html#gov-09", "s": "Human Oversight & Governance", "k": "Compliance Telco Training is a new purpose  Check you re allowed "}, {"t": "15.10 Real-time emotion detection on call-centre agents", "u": "governance.html#gov-10", "s": "Human Oversight & Governance", "k": "Compliance Telco Critical Classify before you deploy  Some uses aren t allowed at all "}, {"t": "15.11 AI vendor dependency never assessed as third-party risk", "u": "governance.html#gov-11", "s": "Human Oversight & Governance", "k": "Compliance FinTech Your model provider is a critical supplier  Manage it like one "}, {"t": "15.12 AI policy document says one thing, the system does another", "u": "governance.html#gov-12", "s": "Human Oversight & Governance", "k": "Compliance Telco A policy without a control is a wish "}, {"t": "15.13 Human overrides are never fed back", "u": "governance.html#gov-13", "s": "Human Oversight & Governance", "k": "Compliance FinTech Every override is a free label "}, {"t": "15.14 Automated postpaid decline with no human review option", "u": "governance.html#gov-14", "s": "Human Oversight & Governance", "k": "Compliance Telco Automated decisions with real effects need a human route "}, {"t": "15.15 Human review queue with no SLA or capacity plan", "u": "governance.html#gov-15", "s": "Human Oversight & Governance", "k": "Compliance FinTech A human in the loop is a service with a capacity "}, {"t": "15.16 Staff paste customer data into public chatbots", "u": "governance.html#gov-16", "s": "Human Oversight & Governance", "k": "Compliance Security Telco Give people a safe tool  or they ll use an unsafe one "}, {"t": "15.17 Pilot runs for two years with no success criteria", "u": "governance.html#gov-17", "s": "Human Oversight & Governance", "k": "Compliance Cost FinTech Every pilot needs a finish line "}, {"t": "15.18 Voice bot unusable for customers with speech impairments", "u": "governance.html#gov-18", "s": "Human Oversight & Governance", "k": "Compliance Telco Design for every customer  not the average one "}, {"t": "15.19 Nobody knows the regulator notification deadline for an AI incident", "u": "governance.html#gov-19", "s": "Human Oversight & Governance", "k": "Compliance FinTech Know your reporting clock before the incident starts it "}, {"t": "15.20 Governance checklist signed but never checked", "u": "governance.html#gov-20", "s": "Human Oversight & Governance", "k": "Compliance Security Telco Governance runs on evidence  not ticks "}, {"t": "16. Hyperscaler Platforms: AWS, Google Cloud & Microsoft", "u": "hyperscalers.html", "s": "Section"}, {"t": "16.1 AWS: Bedrock Knowledge Bases with default settings for complex documents", "u": "hyperscalers.html#aws-kb-defaults", "s": "Hyperscaler Platforms", "k": "Quality A managed RAG service removes the plumbing  not the design decisions  Configure parsing  chunking  metadata and hybrid retrieval  then evaluate "}, {"t": "16.2 AWS: New agents built on legacy Bedrock Agents with monolithic action groups", "u": "hyperscalers.html#aws-agents-classic", "s": "Hyperscaler Platforms", "k": "Reliability Security Scale On AWS  new agent work belongs on AgentCore  any framework  MCP tools through Gateway  and deterministic Cedar policies outside the model "}, {"t": "16.3 AWS: Guardrails on the input only, or not attached at all", "u": "hyperscalers.html#aws-guardrails-partial", "s": "Hyperscaler Platforms", "k": "Security Compliance A guardrail that only checks one direction is half a control  Cover input and output  check grounding  version it  and enforce it centrally "}, {"t": "16.4 AWS: Provisioned Throughput bought too early, batch never used", "u": "hyperscalers.html#aws-capacity-misfit", "s": "Hyperscaler Platforms", "k": "Cost Pick capacity modes from measured workload shape  on demand for spiky  provisioned for steady  batch for anything that can wait "}, {"t": "16.5 AWS: Cross-region inference enabled without a data-residency review", "u": "hyperscalers.html#aws-cross-region-residency", "s": "Hyperscaler Platforms", "k": "Compliance Inference routing is a data residency decision  Map profiles to data classification and enforce it with policy  not convention "}, {"t": "16.6 Google Cloud: Grounding with Google Search for regulated internal answers", "u": "hyperscalers.html#gcp-search-grounding-regulated", "s": "Hyperscaler Platforms", "k": "Compliance Quality Choose grounding sources deliberately  Internal policy answers should only ever be grounded in governed internal data "}, {"t": "16.7 Google Cloud: Long-context prompts re-sent without context caching", "u": "hyperscalers.html#gcp-long-context-no-cache", "s": "Hyperscaler Platforms", "k": "Cost Latency A large context window without caching re bills the same document on every call  Cache stable prefixes and keep retrieval for pinpoint questions "}, {"t": "16.8 Google Cloud: No VPC Service Controls perimeter around AI services", "u": "hyperscalers.html#gcp-no-vpcsc", "s": "Hyperscaler Platforms", "k": "Security Compliance On Google Cloud  IAM decides who can call AI APIs  VPC Service Controls decides from where  and what data can leave  Regulated workloads need both "}, {"t": "16.9 Google Cloud: ADK agents deployed without evaluation in the release path", "u": "hyperscalers.html#gcp-adk-no-evals", "s": "Hyperscaler Platforms", "k": "Quality Reliability Easy deployment makes evaluation gates more important  not less  Evaluate agent trajectories in CI before anything reaches the runtime "}, {"t": "16.10 Microsoft: PTU sizing guesses and no 429 handling", "u": "hyperscalers.html#azure-ptu-throttling", "s": "Hyperscaler Platforms", "k": "Cost Reliability Size PTUs for the baseline  spill peaks to pay as you go through a gateway  and pick deployment types for residency first  capacity second "}, {"t": "16.11 Microsoft: Quick-start \"chat with your data\" treated as the production RAG platform", "u": "hyperscalers.html#azure-on-your-data", "s": "Hyperscaler Platforms", "k": "Quality Scale Wizard generated RAG gets you a demo  Production needs a designed index  hybrid plus semantic ranking  and security trimming tied to Entra ID "}, {"t": "16.12 Microsoft: API keys instead of Entra ID and managed identities", "u": "hyperscalers.html#azure-key-auth", "s": "Hyperscaler Platforms", "k": "Security On Azure  every AI caller  app or agent  should be an Entra identity with least privilege RBAC  Disable keys "}, {"t": "16.13 Microsoft: Content filters left at defaults, with no Prompt Shields or custom blocklists", "u": "hyperscalers.html#azure-content-safety-defaults", "s": "Hyperscaler Platforms", "k": "Security Compliance Default safety settings are a starting point  Tune filters per domain  shield documents as well as prompts  and measure false positives "}, {"t": "16.14 Cross-cloud: Hard lock-in to one platform's agent SDK", "u": "hyperscalers.html#cloud-sdk-lockin", "s": "Hyperscaler Platforms", "k": "Cost Scale Use managed runtimes  but own the seams  Open frameworks  MCP tools and OpenTelemetry keep agents portable across clouds "}, {"t": "16.15 Cross-cloud: Multi-cloud AI just because", "u": "hyperscalers.html#multicloud-by-default", "s": "Hyperscaler Platforms", "k": "Cost Compliance Multi cloud should be a justified exception  not a default  Pick a primary platform by data gravity and add others only for named reasons "}, {"t": "16.16 Cross-cloud: Choosing a platform by model benchmarks alone", "u": "hyperscalers.html#platform-by-benchmark", "s": "Hyperscaler Platforms", "k": "Cost Adoption Choose an AI platform for its data  identity and operating fit  Models move every month  your data estate doesn t "}, {"t": "17. Local LLMs vs Hyperscaler Hosting (Cost Management)", "u": "local-vs-cloud.html", "s": "Section"}, {"t": "17.1 Self-hosting \"to save money\" at low or spiky usage", "u": "local-vs-cloud.html#selfhost-low-volume", "s": "Local LLMs vs Cloud Cost", "k": "Cost Self hosting trades variable cost for fixed cost  It only pays off when steady usage is high enough to keep GPUs busy  and people are counted in the TCO "}, {"t": "17.2 Comparing token prices while ignoring operations and quality", "u": "local-vs-cloud.html#token-price-only", "s": "Local LLMs vs Cloud Cost", "k": "Cost Quality The right unit is cost per correct outcome  not cost per token  Price the errors and the operating team before claiming savings "}, {"t": "17.3 Unoptimized self-hosted serving (no batching, quantization or KV cache reuse)", "u": "local-vs-cloud.html#inefficient-serving", "s": "Local LLMs vs Cloud Cost", "k": "Cost Latency If you self host  the serving stack is the cost lever  Continuous batching  prefix caching and validated quantization decide how many GPUs you need "}, {"t": "17.4 All-or-nothing hosting with no hybrid routing", "u": "local-vs-cloud.html#no-hybrid-routing", "s": "Local LLMs vs Cloud Cost", "k": "Cost Quality Local versus cloud is a routing decision  not a religion  Send each request to the cheapest compliant model that meets its quality bar "}, {"t": "17.5 Assuming \"local\" automatically means secure and compliant", "u": "local-vs-cloud.html#local-equals-compliant", "s": "Local LLMs vs Cloud Cost", "k": "Security Compliance On prem isn t automatically secure  Verify the model supply chain  review licenses  patch the stack  and hold local models to the same controls as cloud "}, {"t": "17.6 No caching layer in front of any model", "u": "local-vs-cloud.html#no-cache-layer", "s": "Local LLMs vs Cloud Cost", "k": "Cost Latency The cheapest model call is the one you don t make  Layer prefix  exact and semantic caches  scoped by permissions and invalidated by source changes "}, {"t": "18. Harness Engineering at Every Stage", "u": "harness.html", "s": "Section"}, {"t": "18.1 Data stage: no golden documents, so parser regressions go unnoticed", "u": "harness.html#harness-data-stage", "s": "Harness Engineering", "k": "Quality Parsing is the first place quality is lost  A golden document harness catches regressions before they spread into every index "}, {"t": "18.2 Retrieval stage: no labelled query set", "u": "harness.html#harness-retrieval-stage", "s": "Harness Engineering", "k": "Quality You can t tune retrieval through the final answer  A labelled query set  with security tests included  makes retrieval an engineering decision "}, {"t": "18.3 Generation stage: no faithfulness harness", "u": "harness.html#harness-generation-stage", "s": "Harness Engineering", "k": "Quality Compliance Evaluate generation with retrieval frozen  Measure claim level faithfulness and refusal behaviour  not how fluent the answer sounds "}, {"t": "18.4 Agent runtime: the prompt treated as the whole agent", "u": "harness.html#harness-runtime-prompt-only", "s": "Harness Engineering", "k": "Reliability Security The model proposes and the harness disposes  Context  tools  sandboxing  hooks and budgets are where agent reliability and safety are actually engineered "}, {"t": "18.5 Agent evaluation: judging only the final answer, not the trajectory", "u": "harness.html#harness-final-answer-only", "s": "Harness Engineering", "k": "Quality Security For agents  how matters as much as what  Evaluate trajectories and safety invariants in simulated multi turn runs "}, {"t": "18.6 Safety: red-teaming once before launch", "u": "harness.html#harness-redteam-once", "s": "Harness Engineering", "k": "Security Red teaming is a regression suite  not an event  Automate attacks  run them on every change  and turn every finding into a permanent test "}, {"t": "18.7 CI/CD: one big eval run instead of a tiered gate", "u": "harness.html#harness-cicd-stage", "s": "Harness Engineering", "k": "Reliability Cost Tier your eval gates like your test pyramid  fast and targeted on every PR  full depth before release  live metrics in canary "}, {"t": "18.8 Production: no online evaluation, drift detection or feedback loop", "u": "harness.html#harness-production-stage", "s": "Harness Engineering", "k": "Quality Reliability Evaluation doesn t end at deployment  Online evals  drift monitors and trace linked feedback keep the harness honest as the world changes "}, {"t": "19. Claude & Other AI Tools", "u": "ai-tools.html", "s": "Section"}, {"t": "19.1 Claude: Large stable prompts re-sent without prompt caching", "u": "ai-tools.html#claude-no-prompt-caching", "s": "Claude & AI Tools", "k": "Cost Latency With Claude  prompt layout is a cost decision  Put stable content first  set cache breakpoints  and check the cache read tokens "}, {"t": "19.2 Claude: Reasoning effort not matched to the task", "u": "ai-tools.html#claude-thinking-misuse", "s": "Claude & AI Tools", "k": "Cost Latency Quality Reasoning effort is a dial  not a switch  Set it per task from eval results  low for routine work and high for planning and analysis "}, {"t": "19.3 Claude: Procedures pasted into every prompt instead of packaged as Skills", "u": "ai-tools.html#claude-skills-ignored", "s": "Claude & AI Tools", "k": "Cost Quality Scale Institutional know how belongs in versioned  on demand Skills  not pasted into every prompt "}, {"t": "19.4 Claude: One model tier for everything", "u": "ai-tools.html#claude-single-tier", "s": "Claude & AI Tools", "k": "Cost Latency Use the model family as a portfolio  small tiers for volume  the middle tier for most production work  the top tier where reasoning is the bottleneck "}, {"t": "19.5 Claude: Computer use where an API exists, or without a sandbox", "u": "ai-tools.html#claude-computer-use-misuse", "s": "Claude & AI Tools", "k": "Security Reliability Cost Computer use is the integration of last resort  Use APIs and MCP first  and when you do drive a screen  do it in a sandbox with checkpoints "}, {"t": "19.6 Claude: Not choosing deliberately between direct and cloud-marketplace access", "u": "ai-tools.html#claude-access-route", "s": "Claude & AI Tools", "k": "Compliance Cost Claude is available through several routes  Choose one deliberately on residency  features and governance  and meter them all through one gateway "}, {"t": "19.7 Frameworks: Prompts tuned to one provider's quirks with no portability layer", "u": "ai-tools.html#provider-quirk-prompts", "s": "Claude & AI Tools", "k": "Reliability Cost Pin behaviour with schemas and evals  not model quirks  so switching models is a measured choice "}, {"t": "19.8 Frameworks: The framework treated as the architecture", "u": "ai-tools.html#framework-as-architecture", "s": "Claude & AI Tools", "k": "Reliability Cost Pick the lightest abstraction that fits the problem  Frameworks are dependencies to manage  not architectures to adopt "}, {"t": "19.9 Coding agents: Measuring adoption by seats and lines of code", "u": "ai-tools.html#coding-adoption-metrics", "s": "Claude & AI Tools", "k": "Adoption Cost Measure AI coding tools by delivery outcomes  lead time  change failure rate  rework   not by seats or lines of code "}, {"t": "19.10 Coding agents: Write access to production repos and systems with no guardrails", "u": "ai-tools.html#coding-agent-unguarded", "s": "Claude & AI Tools", "k": "Security Reliability Give coding agents a sandbox  least privilege credentials  deny rules for destructive commands  and a PR only path to shared branches "}, {"t": "19.11 Coding agents: No repository context or conventions files", "u": "ai-tools.html#coding-no-context-files", "s": "Claude & AI Tools", "k": "Quality Adoption Coding agents are only as good as the context they start with  Codify conventions in versioned repo context files and shared skills "}, {"t": "19.12 Coding agents: AI-generated code shipped without security and dependency scanning", "u": "ai-tools.html#coding-no-security-scan", "s": "Claude & AI Tools", "k": "Security AI generated code needs the same or a higher security bar  Scan everything and verify every new dependency "}, {"t": "19.13 Workplace assistants: Enterprise rollout before fixing oversharing", "u": "ai-tools.html#assistant-oversharing", "s": "Claude & AI Tools", "k": "Security Compliance Workplace assistants respect permissions perfectly  including the wrong ones  Fix oversharing before switching AI on "}, {"t": "19.14 Workplace assistants: Licenses with no enablement, use-case catalog or ROI tracking", "u": "ai-tools.html#assistant-no-enablement", "s": "Claude & AI Tools", "k": "Adoption Cost A workplace AI rollout is change management  not provisioning  Use persona playbooks  champions  sanctioned advanced paths and measured value "}, {"t": "19.15 Workplace assistants: Banning AI tools with no sanctioned alternative", "u": "ai-tools.html#shadow-ai-ban", "s": "Claude & AI Tools", "k": "Security Adoption Banning AI without a sanctioned alternative creates shadow AI  Make the governed path the easiest one "}, {"t": "20. AI Leadership Anti-Patterns", "u": "leadership.html", "s": "Section"}, {"t": "20.1 Proof-of-concept purgatory", "u": "leadership.html#poc-purgatory", "s": "Leadership Anti-Patterns", "k": "Adoption Cost Run pilots that are designed to graduate  production platform  agreed exit criteria  and a scale or stop decision on a fixed date "}, {"t": "20.2 Technology-first use-case selection", "u": "leadership.html#tech-first-use-cases", "s": "Leadership Anti-Patterns", "k": "Adoption Cost Start from value pools  not technology  Score by value  feasibility and risk  then use the simplest technique that works "}, {"t": "20.3 Every team builds its own AI stack", "u": "leadership.html#no-platform-team", "s": "Leadership Anti-Patterns", "k": "Cost Scale Security Build the paved road once  A shared AI platform turns every new use case into configuration plus domain work  and makes security reviews fast "}, {"t": "20.4 Measuring success by model accuracy instead of business KPIs", "u": "leadership.html#accuracy-not-kpis", "s": "Leadership Anti-Patterns", "k": "Adoption Accuracy is an input  not an outcome  Tie model metrics to business KPIs through a value tree  and redesign the process to capture the value "}, {"t": "20.5 Ignoring change management and workforce impact", "u": "leadership.html#ignoring-change-management", "s": "Leadership Anti-Patterns", "k": "Adoption AI adoption is a people change  Co design  communicate  train  and realign incentives  or the best tool goes unused "}, {"t": "20.6 Building everything, or buying everything", "u": "leadership.html#build-everything-or-buy-everything", "s": "Leadership Anti-Patterns", "k": "Leadership Cost Build what differentiates  buy what s commodity  and keep the seams portable  Decide per layer  not once for the stack "}, {"t": "20.7 Chasing leaderboards and model churn", "u": "leadership.html#leaderboard-churn", "s": "Leadership Anti-Patterns", "k": "Leadership Quality Cost Treat new models as candidates  not upgrades  A gateway plus your own evals turns model churn into routine  per route decisions "}, {"t": "20.8 Governance bolted on at the end", "u": "leadership.html#governance-bolted-on", "s": "Leadership Anti-Patterns", "k": "Leadership Compliance Governance that arrives at the end blocks launches  Tier risk at intake and build the controls into the paved road "}, {"t": "20.9 The wrong team shape for applied AI", "u": "leadership.html#wrong-team-shape", "s": "Leadership Anti-Patterns", "k": "Leadership Adoption Applied AI is a delivery loop  not a research problem  Staff every stage  from data and evals to product and adoption "}, {"t": "20.10 Launch and leave", "u": "leadership.html#launch-and-leave", "s": "Leadership Anti-Patterns", "k": "Leadership Quality Reliability AI quality decays without ownership  Run AI features as products with SLOs  a weekly failure review and change management "}, {"t": "20.11 Overpromising to executives", "u": "leadership.html#overpromising-to-executives", "s": "Leadership Anti-Patterns", "k": "Leadership Adoption Probabilistic systems need scenario based commitments  Offer trade offs with evidence  agree guardrail metrics  and report against them "}, {"t": "20.12 System design that starts with the model", "u": "leadership.html#design-starts-with-the-model", "s": "Leadership Anti-Patterns", "k": "Leadership Quality Start from requirements and risk  and choose the model last  A design should trace every requirement to a component "}, {"t": "21. Capstone: Enterprise Agentic AI Reference Architecture", "u": "capstone.html", "s": "Section"}];